update articles set
  cover_image_url = 'https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787649987669-apa-itu-mas-kahwin-kad-tajuk.png',
  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787649987669-apa-itu-mas-kahwin-kad-tajuk/low.webp","sizeBytes":8458},"high":{"url":"https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787649987669-apa-itu-mas-kahwin-kad-tajuk/high.webp","sizeBytes":29528},"original":{"url":"https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787649987669-apa-itu-mas-kahwin-kad-tajuk.png","sizeBytes":32153}}'::jsonb,
  cover_image_smart_crops = '{"crop-16x9-og":{"url":"https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787649987669-apa-itu-mas-kahwin-kad-tajuk/crop-16x9-og.webp?v=0.4688_0.4672-g48c0b959","width":1200,"height":630},"crop-4x3-article-card":{"url":"https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787649987669-apa-itu-mas-kahwin-kad-tajuk/crop-4x3-article-card.webp?v=0.4688_0.4672-g48c0b959","width":1600,"height":1200},"crop-4x5-mobile-cover":{"url":"https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787649987669-apa-itu-mas-kahwin-kad-tajuk/crop-4x5-mobile-cover.webp?v=0.4688_0.4672-g48c0b959","width":1920,"height":2400},"crop-4.3x1-desktop-hero":{"url":"https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787649987669-apa-itu-mas-kahwin-kad-tajuk/crop-4.3x1-desktop-hero.webp?v=0.4688_0.4672-g48c0b959","width":2464,"height":700}}'::jsonb,
  cover_image_focal_point = '{"x":0.4687500000000001,"y":0.4672,"method":"saliency"}'::jsonb,
  cover_image_detection_data = '{"faces":{"disabled":"rekognition"},"labels":{"disabled":"rekognition"}}'::jsonb,
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Maksud mas kahwin, atau mahar, ialah bayaran yang wajib dibayar oleh suami kepada isteri pada masa akad nikah. Takrif itu datang daripada seksyen 2 enakmen undang-undang keluarga Islam negeri, dan Jabatan Mufti Wilayah Persekutuan menyatakan mahar itu hak mutlak isteri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Mahar ialah istilah Arab yang merujuk perkara yang sama. Ia bukan hantaran, dan bukan duit hantaran.","type":"text"}]},{"type":"figureBlock","attrs":{"alt":"Pasangan pengantin Melayu duduk berdampingan di sofa putih selepas akad nikah. Pengantin lelaki berbaju melayu putih dengan samping berbenang emas dan bersongkok hitam. Pengantin perempuan berbaju putih, bertudung bersulam dengan selendang panjang, memegang jambangan bunga ros oren muda. Latar belakang kain putih berjalur hijau dan merah jambu lembut.","src":"https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787649987669-images-s-pengantin-selepas-akad-azlan-dupree/high.webp","data-caption":"Kredit: Azlan DuPree (CC BY 2.0)","data-caption-url":"https://commons.wikimedia.org/wiki/File:Malay_couple.jpg"}},{"type":"paragraph","content":[{"text":"Enakmen ialah undang-undang yang diluluskan oleh dewan undangan negeri. Seksyen 2 Enakmen Undang-Undang Keluarga Islam (Negeri Pulau Pinang) 2004 menyebutnya begitu:","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"\"pembayaran kahwin yang wajib dibayar di bawah Hukum Syarak oleh suami kepada isteri pada masa perkahwinan diakadnikahkan\"","type":"text"}]}]},{"type":"paragraph","content":[{"text":"Hukum Syarak di sini bermaksud hukum Islam yang menjadi rujukan undang-undang keluarga Islam.","type":"text"}]},{"type":"paragraph","content":[{"text":"Takrif yang sama, perkataan demi perkataan, ada dalam enakmen Melaka 2002, Kedah 2008 dan Terengganu 2017. Enakmen Sabah 2004 membawa takrif yang sama dalam teks bahasa Inggerisnya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiga istilah ini kerap bertukar tempat dalam perbualan keluarga. Ini bezanya.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph"}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Mas kahwin","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Hantaran","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Duit hantaran","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Wajib atau adat","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Wajib","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Adat","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Adat","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Diberi kepada siapa","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Isteri","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Keluarga pengantin","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Keluarga pengantin perempuan","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Siapa yang memilikinya","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Isteri sepenuhnya","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Penerima dulang","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Keluarga penerima","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Siapa menetapkan jumlah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kadar minimum ditetapkan pihak berkuasa agama negeri","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Persetujuan dua keluarga","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Persetujuan dua keluarga","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Sumber baris \"wajib\": Enakmen Undang-Undang Keluarga Islam (Negeri Pulau Pinang) 2004, seksyen 2, dan Jabatan Mufti Pulau Pinang. Kadar minimum ditetapkan oleh pihak berkuasa agama negeri masing-masing, dan tidak semua negeri menetapkan satu.","type":"text"}]},{"type":"paragraph","content":[{"text":"Borang rasmi yang dijadualkan dalam enakmen Melaka 2002 merekodkan mas kahwin, hantaran dan pemberian lain sebagai tiga medan berasingan. Satu borang Melaka melabelkannya \"Belanja hantaran\". Disemak pada Ogos 2026.","type":"text"}]},{"type":"paragraph","content":[{"text":"Perbezaan ketiga-tiganya dihuraikan penuh dalam ","type":"text"},{"text":"hantaran dan mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Kenapa mas kahwin wajib, dan siapa pemiliknya?","type":"text"}]},{"type":"paragraph","content":[{"text":"Lima enakmen negeri yang disemak menyebutnya wajib, dan pemiliknya ialah isteri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jabatan Mufti Pulau Pinang menyatakan mas kahwin ialah pemberian yang wajib diberikan kepada isteri apabila akad nikah sudah termeterai.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pemilikan itu dinyatakan dengan tegas dalam Irsyad Hukum Ke-198, Jabatan Mufti Wilayah Persekutuan, bertarikh 30 Mei 2017: \"Mahar pernikahan adalah hak mutlak isteri\", bukan hak wali atau keluarganya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Bolehkah keluarga pengantin perempuan mengambilnya? Tidak. Hak itu milik isteri sepenuhnya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jawapan yang sama menyentuh soal suami menggunakan mahar isteri, dan ia ada dua bahagian.","type":"text"}]},{"type":"paragraph","content":[{"text":"\"Haram hukumnya bagi suami memakan/menggunakan/mengambil manfaat daripada mahar isteri jika tanpa kerelaan dan kebenaran isteri.\" Sebaliknya, \"Harus hukumnya... jika dengan kerelaan dan kebenaran isteri\", iaitu dibenarkan apabila isteri sendiri merelakannya.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Apakah fungsi mas kahwin?","type":"text"}]},{"type":"paragraph","content":[{"text":"Ia lambang penghargaan, dan sumber rasmi menyebutnya begitu.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dalam Al-Kafi #1395 bertarikh 13 Oktober 2019, Jabatan Mufti Wilayah Persekutuan menyimpulkan bahawa \"penetapan mas kahwin mempunyai pelbagai hikmah yang tersendiri\". Antaranya \"bagi menzahirkan kemuliaan kaum wanita\" dan \"sebagai tanda kesungguhan lelaki dalam membina hubungan dengan seseorang wanita\".","type":"text"}]},{"type":"paragraph","content":[{"text":"Jabatan itu memetik kitab ","type":"text"},{"text":"Fatawa Mu''asirah","type":"text","marks":[{"type":"italic"}]},{"text":" karya Syeikh Yusuf al-Qaradhawi bagi kenyataan tersebut.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Beza mas kahwin, hantaran dan duit hantaran","type":"text"}]},{"type":"paragraph","content":[{"text":"Hantaran ialah barang yang bertukar antara dua keluarga mengikut adat. Duit hantaran, juga disebut wang hantaran dalam dokumen rasmi, ialah wang yang diberikan pihak lelaki kepada keluarga pengantin perempuan berdasarkan persetujuan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Warta Kerajaan Negeri Perak, Pk. P.U. 30, menyusun medannya sama. Medan hantaran duduk terus di bawah medan mas kahwin, diikuti medan pemberian lain.","type":"text"}]},{"type":"paragraph","content":[{"text":"Fatwa Selangor yang diwartakan pada 4 Februari 2010 menyebut: \"Sekiranya terdapat wang hantaran daripada pihak lelaki, ianya dikira sebagai Maskahwin.\" Ketetapan itu milik Selangor sahaja, dan tidak boleh dipindahkan ke negeri lain.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Perlukah mas kahwin dalam bentuk wang?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tidak semestinya. Ia boleh berupa barang, asalkan barang itu boleh dinilai dengan wang.","type":"text"}]},{"type":"paragraph","content":[{"text":"Takrif dalam enakmen Pulau Pinang 2004 menerima mas kahwin \"berupa sesuatu yang menurut Hukum Syarak, dapat dinilai dengan wang\".","type":"text"}]},{"type":"paragraph","content":[{"text":"Pejabat agama pula lebih suka angka yang jelas, atas sebab pentadbiran. Halaman Jabatan Hal Ehwal Agama Islam Perlis (JAIPS) bertarikh 23 April 2019 menyatakannya begitu:","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"\"tidak menggalakkan mahar yang tidak dapat diletakkan harga secara jelas seperti mengajar surah al-Fatihah atau surah al-Ikhlas oleh pengantin lelaki kepada pengantin perempuan\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Sumber: JAIPS, \"Tatacara Perkahwinan Umat Islam di Negeri Perlis\", perenggan 5.2","type":"text"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Apa beza mas kahwin tunai dan mas kahwin hutang?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tunai bermaksud diserahkan pada hari akad. Hutang bermaksud dijanjikan dan dijelaskan kemudian.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kedua-duanya diiktiraf dalam takrif yang sama. Enakmen menerima mas kahwin \"berupa wang yang sebenarnya dibayar atau diakui sebagai hutang dengan atau tanpa cagaran\".","type":"text"}]},{"type":"paragraph","content":[{"text":"Borang rasmi negeri pun sudah menyediakan ruang untuk pilihan itu. Kaedah-Kaedah Undang-Undang Keluarga Islam (Borang dan Fi) 2013 disiarkan dalam Warta Kerajaan Negeri Perak, Pk. P.U. 30, bertarikh 1 Jun 2013.","type":"text"}]},{"type":"paragraph","content":[{"text":"Borang 7 di bawah kaedah-kaedah itu, iaitu permohonan mendaftarkan perkahwinan luar negeri dan perkahwinan sukarela, membawa medan \"Mas Kahwin :…………………………………… Tunai / Hutang\".","type":"text"}]},{"type":"paragraph","content":[{"text":"Borang permohonan perceraian dan pembubaran nikah turut meminta mas kahwin dinyatakan sebagai tunai atau hutang, berserta jumlahnya.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Bila mas kahwin diserahkan?","type":"text"}]},{"type":"paragraph","content":[{"text":"Ia biasanya diserahkan pada majlis akad.","type":"text"}]},{"type":"paragraph","content":[{"text":"Seksyen 21(1) enakmen Pulau Pinang 2004 menyebut mas kahwin \"hendaklah biasanya dibayar\" oleh pihak lelaki atau wakilnya, kepada pihak perempuan atau wakilnya. Perkataan \"biasanya\" ialah perkataan enakmen itu sendiri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Seksyen itu juga menyebut penyerahan berlaku di hadapan orang yang mengakadnikahkan perkahwinan itu, dan sekurang-kurangnya dua orang saksi lain.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Jika mas kahwin tidak dijelaskan?","type":"text"}]},{"type":"paragraph","content":[{"text":"Bahagian yang belum dijelaskan direkodkan sebagai hutang oleh Pendaftar, mengikut seksyen 21(2) enakmen Pulau Pinang 2004. Pendaftar merekodkan bahagian itu, tarikh yang dijanjikan untuk penjelasan, dan butiran apa-apa cagaran.","type":"text"}]},{"type":"paragraph","content":[{"text":"Seksyen 59 enakmen yang sama pula bercakap tentang keadaan lain, iaitu apabila perkahwinan dibubarkan. Ia menyebut tiada apa-apa dalam enakmen itu boleh menyentuh hak isteri terhadap mas kahwin dan pemberiannya pada waktu itu. Seksyen itu tidak menyentuh tunggakan dalam perkahwinan yang masih berjalan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pejabat Agama Islam Daerah (PAID) merekodkan mas kahwin, tetapi ia bukan tempat untuk menuntutnya. Tuntutan antara suami isteri didengar di Mahkamah Syariah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Di Pulau Pinang, bidang kuasa itu datang daripada seksyen 61(3)(b) Enakmen Pentadbiran Agama Islam (Negeri Pulau Pinang) 2004. Seksyen itu meletakkan perkara yang berkaitan dengan perhubungan antara suami isteri, dan tuntutan harta yang berbangkit daripadanya, di bawah Mahkamah Tinggi Syariah. Enakmen itu tidak menyebut \"mas kahwin\" secara khusus.","type":"text"}]},{"type":"paragraph","content":[{"text":"Setiap negeri mempunyai enakmen pentadbirannya sendiri, jadi rujuk Mahkamah Syariah di negeri perkahwinan itu didaftarkan.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Bagaimana jika keluarga anda buat cara berbeza?","type":"text"}]},{"type":"paragraph","content":[{"text":"Mulakan dengan apa yang tetap, kerana bahagian itu tidak boleh dirundingkan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang tetap: mas kahwin wajib dan ia milik isteri. Yang berbeza mengikut keluarga, adat dan negeri ialah hantaran dan duit hantaran, dan kedua-duanya bukan mas kahwin.","type":"text"}]},{"type":"paragraph","content":[{"text":"Rundingkan dua perkara itu secara berasingan, dan tetapkan mas kahwin dahulu sebelum membincangkan hantaran.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kadar minimum pula ditetapkan oleh setiap negeri sendiri, jadi baris yang anda rujuk ialah negeri tempat perkahwinan didaftarkan. Kadar itu ialah lantai, bukan jumlah yang perlu dibayar. Senarai penuh setiap negeri, berserta pihak berkuasa dan tarikhnya, ada dalam ","type":"text"},{"text":"mas kahwin ikut negeri","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-ikut-negeri","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Jika keluarga anda ingin meletakkan jumlah lebih tinggi daripada lantai itu, bacaan seterusnya ialah ","type":"text"},{"text":"mas kahwin melebihi kadar minimum","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-melebihi-kadar-minimum","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]}]}'::jsonb,
  updated_at = now()
where id = 'fc26f9b1-f4ba-4982-8a26-558ba74d14b8';

-- mas-kahwin-ikut-negeri  (updated_at was 2026-08-25T09:11:25.886Z)
update articles set
  cover_image_url = 'https://images.hellokahwin.com/inspire/mas-kahwin-ikut-negeri/1787649072308-mas-kahwin-ikut-negeri-kad-tajuk.png',
  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-ikut-negeri/1787649072308-mas-kahwin-ikut-negeri-kad-tajuk/low.webp","sizeBytes":11428},"high":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-ikut-negeri/1787649072308-mas-kahwin-ikut-negeri-kad-tajuk/high.webp","sizeBytes":38828},"original":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-ikut-negeri/1787649072308-mas-kahwin-ikut-negeri-kad-tajuk.png","sizeBytes":41596}}'::jsonb,
  cover_image_smart_crops = '{"crop-16x9-og":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-ikut-negeri/1787649072308-mas-kahwin-ikut-negeri-kad-tajuk/crop-16x9-og.webp?v=0.5938_0.4992-g48c0b959","width":1200,"height":630},"crop-4x3-article-card":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-ikut-negeri/1787649072308-mas-kahwin-ikut-negeri-kad-tajuk/crop-4x3-article-card.webp?v=0.5938_0.4992-g48c0b959","width":1600,"height":1200},"crop-4x5-mobile-cover":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-ikut-negeri/1787649072308-mas-kahwin-ikut-negeri-kad-tajuk/crop-4x5-mobile-cover.webp?v=0.5938_0.4992-g48c0b959","width":1920,"height":2400},"crop-4.3x1-desktop-hero":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-ikut-negeri/1787649072308-mas-kahwin-ikut-negeri-kad-tajuk/crop-4.3x1-desktop-hero.webp?v=0.5938_0.4992-g48c0b959","width":2464,"height":700}}'::jsonb,
  cover_image_focal_point = '{"x":0.5937500000000001,"y":0.4992,"method":"saliency"}'::jsonb,
  cover_image_detection_data = '{"faces":{"disabled":"rekognition"},"labels":{"disabled":"rekognition"}}'::jsonb,
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Kadar minimum mas kahwin ikut negeri ditetapkan oleh pihak berkuasa agama negeri masing-masing, bukan oleh satu kadar kebangsaan. Angka yang direkodkan bermula RM22.50, iaitu kadar Johor yang belum disahkan semula, hingga RM300 di Selangor dan Wilayah Persekutuan. Enam daripada 14 bidang kuasa tidak menetapkan sebarang kadar minimum, dan di situ jumlahnya ditentukan melalui persetujuan lalu direkodkan oleh pejabat agama daerah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Mas kahwin ialah bayaran yang wajib dibayar oleh suami kepada isteri, dan enakmen undang-undang keluarga Islam negeri mentakrifkannya begitu. Ia berbeza daripada hantaran dan daripada duit hantaran, dan bezanya diterangkan berserta sumbernya dalam ","type":"text"},{"text":"apa itu mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/apa-itu-mas-kahwin","class":null,"target":"_blank"}}]},{"text":". Yang disenaraikan di bawah ialah kadar minimum pentadbiran, iaitu angka yang ditetapkan oleh pihak berkuasa agama negeri.","type":"text"}]},{"type":"figureBlock","attrs":{"alt":"Majlis bersanding: pengantin duduk di pelamin di bawah gerbang bunga merah jambu dan putih. Pengantin lelaki berbaju melayu merah jambu bersamping dan bersongkok, pengantin perempuan berbaju merah jambu bertudung sambil memegang jambangan kecil. Seorang pengapit lelaki di kiri dan seorang pengapit perempuan di kanan mengipas pasangan itu.","src":"https://images.hellokahwin.com/inspire/mas-kahwin-ikut-negeri/1787649072308-images-s-bersanding-pelamin-mohd-hasan/high.webp","data-caption":"Kredit: mohd hasan / Pexels","data-caption-url":"https://www.pexels.com/photo/portrait-of-newlywed-couple-15430952/"}},{"type":"heading","attrs":{"level":3},"content":[{"text":"Kadar minimum mas kahwin mengikut negeri","type":"text"}]},{"type":"paragraph","content":[{"text":"Jadual ini menyenaraikan kesemua 14 bidang kuasa. Setiap angka membawa pihak berkuasa yang menetapkannya dan tarikh ia ditetapkan.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Negeri","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kadar minimum","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Anak dara / janda","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pihak berkuasa","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tarikh ditetapkan","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Perlis","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kadar minimum ditetapkan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada pembezaan dinyatakan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Jabatan Hal Ehwal Agama Islam Perlis (JAIPS)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dinyatakan dalam dokumen tatacara perkahwinan bertarikh 23 April 2019","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kedah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kadar minimum ditetapkan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada pembezaan dinyatakan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Enakmen Undang-Undang Keluarga Islam (Kedah Darul Aman) 2008, seksyen 21","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Enakmen 2008 dan Kaedah-Kaedah Borang dan Fi 2019 tidak menetapkan sebarang jumlah","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pulau Pinang","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kadar minimum ditetapkan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada pembezaan dinyatakan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Enakmen Undang-Undang Keluarga Islam (Negeri Pulau Pinang) 2004, seksyen 21","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Enakmen 2004 tidak menetapkan sebarang jumlah","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Perak","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kadar minimum ditetapkan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada pembezaan dinyatakan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Warta Kerajaan Negeri Perak, Pk. P.U. 30","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Warta 1 Jun 2013 tidak menetapkan sebarang jumlah","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Selangor","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM300","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Sama bagi anak dara dan janda, tanpa had maksimum","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Fatwa diwartakan, Jawatankuasa Fatwa Negeri Selangor","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Fatwa bertarikh 31 Disember 2009, berkuat kuasa 1 Januari 2010","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Wilayah Persekutuan (Kuala Lumpur, Putrajaya, Labuan)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM300, iaitu \"tidak kurang daripada RM300.00\"","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada pembezaan dinyatakan; satu kadar bagi seluruh Wilayah Persekutuan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Majlis Agama Islam Wilayah Persekutuan (MAIWP), dilaporkan oleh Jabatan Agama Islam Wilayah Persekutuan (JAWI)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Mesyuarat 22 Februari 2023, perkenan 19 Mei 2023, berkuat kuasa 1 Oktober 2023","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Negeri Sembilan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM200 anak dara atau bujang; RM100 janda atau ibu tunggal","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Ya, dinyatakan secara berasingan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Jabatan Hal Ehwal Agama Islam Negeri Sembilan (JHEAINS)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tarikh penetapan tidak dinyatakan; dokumen JHEAINS bertarikh 13 Mei 2026","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Melaka","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM100","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada pembezaan dinyatakan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Majlis Agama Islam Melaka (MAIM)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Mesyuarat 28 Disember 2015, berkuat kuasa 1 Jun 2016","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Johor","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM22.50, ","type":"text"},{"text":"belum disahkan sebagai kadar semasa","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada pembezaan dinyatakan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Modul kursus praperkahwinan, bukan penerbitan kerajaan negeri Johor","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Sumber terbaik bertarikh 2019/2020 dan 2022","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pahang","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM100","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada pembezaan dinyatakan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Titah KDYMM Sultan Pahang, dilaporkan oleh RTM","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"28 Mac 2024; tarikh kuat kuasa tidak dinyatakan dalam mana-mana sumber","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Terengganu","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kadar minimum ditetapkan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada pembezaan dinyatakan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pesuruhjaya Jabatan Hal Ehwal Agama Terengganu, M. Rozi Bidin, dipetik Utusan Malaysia","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kenyataan bertarikh 29 Mac 2024","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kelantan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kadar minimum ditetapkan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada pembezaan dinyatakan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kenyataan rasmi negeri ditemui; disenaraikan \"tiada ketetapan\" dalam modul kursus praperkahwinan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Modul bertarikh 2019/2020","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Sabah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM100, ","type":"text"},{"text":"belum disahkan sebagai kadar semasa","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada pembezaan dinyatakan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Modul kursus praperkahwinan sahaja; Enakmen Undang-Undang Keluarga Islam 2004 tidak menetapkan jumlah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Modul bertarikh 2019/2020","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Sarawak","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM120, ","type":"text"},{"text":"belum disahkan sebagai kadar semasa","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada pembezaan dinyatakan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Modul kursus praperkahwinan; petikan akhbar 2009; Ordinan Undang-Undang Keluarga Islam 2001 tidak menetapkan jumlah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Modul 2019/2020; petikan bertarikh 14 Disember 2009","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Disemak pada Ogos 2026.","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Tiga baris membawa label ","type":"text"},{"text":"belum disahkan sebagai kadar semasa","type":"text","marks":[{"type":"bold"}]},{"text":", iaitu Johor, Sabah dan Sarawak. Angka itu wujud, tetapi tiada laman kerajaan negeri berkenaan yang menerbitkannya pada hari ini, dan sumber terbaik yang ditemui sudah berusia beberapa tahun.","type":"text"}]},{"type":"paragraph","content":[{"text":"Labuan tidak mempunyai baris sendiri kerana kadar RM300 itu dinyatakan bagi seluruh Wilayah Persekutuan, tanpa angka berasingan bagi mana-mana wilayah, mengikut kenyataan JAWI bertarikh 14 Ogos 2023.","type":"text"}]},{"type":"paragraph","content":[{"text":"Angka yang beredar luas bagi Perak, Pulau Pinang dan Kedah tidak dapat dikesan kepada mana-mana sumber kerajaan negeri. Kerana itu ia tidak dicetak di sini.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Siapa yang menetapkan kadar mas kahwin?","type":"text"}]},{"type":"paragraph","content":[{"text":"Kadar ditetapkan oleh pihak berkuasa agama di negeri masing-masing, dan caranya berbeza dari satu negeri ke satu negeri. Setiap negeri mempunyai enakmen undang-undang keluarga Islamnya sendiri, iaitu undang-undang yang diluluskan oleh dewan undangan negeri, serta jabatan agamanya sendiri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Empat mekanisme berbeza menghasilkan angka dalam jadual di atas.","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fatwa yang diwartakan.","type":"text","marks":[{"type":"bold"}]},{"text":" Selangor menetapkan RM300 melalui fatwa yang disiarkan dalam Warta Kerajaan Negeri Selangor pada 4 Februari 2010.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Keputusan majlis agama Islam negeri.","type":"text","marks":[{"type":"bold"}]},{"text":" MAIWP menetapkan RM300 dalam mesyuarat 22 Februari 2023, dan MAIM menaikkan kadar Melaka kepada RM100 dalam mesyuarat 28 Disember 2015.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Titah pemerintah negeri.","type":"text","marks":[{"type":"bold"}]},{"text":" Kadar RM100 di Pahang bermula daripada titah KDYMM Sultan Pahang pada 28 Mac 2024, dilaporkan RTM pada hari yang sama.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dokumen jabatan.","type":"text","marks":[{"type":"bold"}]},{"text":" Negeri Sembilan menerbitkan kadarnya dalam dokumen urusan perkahwinan JHEAINS, halaman 10.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Enam bidang kuasa yang selebihnya tidak menggunakan mana-mana mekanisme itu. Enakmen negeri berkenaan mentakrifkan mas kahwin dan mewajibkan Pendaftar Nikah merekodkan nilainya, tetapi tidak menetapkan sebarang jumlah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Fatwa Selangor ialah teks paling terperinci dalam jadual ini, dan ia menyebut satu perkara yang jarang dilaporkan dengan tepat:","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"\"Menetapkan had minima kadar nilai Maskahwin sebanyak RM 300.00 bagi anak dara atau janda tanpa ada had maksima. Sekiranya terdapat wang hantaran daripada pihak lelaki, ianya dikira sebagai Maskahwin.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Sumber: Warta Kerajaan Negeri Selangor, Jil. 63 No. 3, 4hb Februari 2010, Sel. P.U. 3","type":"text"}]}]},{"type":"paragraph","content":[{"text":"Ketetapan bahawa wang hantaran dikira sebagai mas kahwin itu khusus untuk Selangor. Tiada negeri lain dalam jadual ini menyatakan perkara yang sama, dan ia tidak boleh diandaikan terpakai di tempat lain.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Enam bidang kuasa yang tidak menetapkan kadar minimum","type":"text"}]},{"type":"paragraph","content":[{"text":"Perlis, Kedah, Pulau Pinang, Perak, Terengganu dan Kelantan tidak menetapkan kadar minimum mas kahwin. Itu jawapan bagi negeri berkenaan, bukan maklumat yang tertinggal daripada jadual.","type":"text"}]},{"type":"paragraph","content":[{"text":"Perlis","type":"text","marks":[{"type":"bold"}]},{"text":" menyatakannya dengan perkataannya sendiri: \"Tiada penetapan jumlah tertentu untuk mahar. Bergantung kepada persetujuan bersama.\" Mahar ialah istilah Arab bagi mas kahwin, dan kedua-duanya merujuk perkara yang sama. Kenyataan itu terdapat dalam dokumen tatacara perkahwinan JAIPS bertarikh 23 April 2019.","type":"text"}]},{"type":"paragraph","content":[{"text":"Terengganu","type":"text","marks":[{"type":"bold"}]},{"text":" disahkan oleh pegawai kanannya sendiri. Pada 29 Mac 2024, Utusan Malaysia melaporkan bahawa tiada sebarang ketetapan dibuat mengenai kadar mas kahwin di Terengganu setakat itu. Laporan itu memetik Pesuruhjaya Jabatan Hal Ehwal Agama Terengganu, M. Rozi Bidin: \"Oleh itu, terpulang kepada kedua-dua keluarga untuk menetapkan kadar mas kahwin yang dipersetujui.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Perak","type":"text","marks":[{"type":"bold"}]},{"text":" disemak melalui wartanya sendiri. Warta Kerajaan Negeri Perak, Pk. P.U. 30 bertarikh 1 Jun 2013, mengandungi 20 sebutan \"mas kahwin\" merentasi 84 halaman, iaitu sepuluh dalam teks Melayu dan sepuluh lagi dalam terjemahan Inggerisnya. Kesemuanya ruang kosong untuk diisi pada borang.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kedah","type":"text","marks":[{"type":"bold"}]},{"text":" dan ","type":"text"},{"text":"Pulau Pinang","type":"text","marks":[{"type":"bold"}]},{"text":" sama keadaannya. Seksyen 21 enakmen kedua-dua negeri mentakrifkan mas kahwin dan mewajibkan Pendaftar merekodkan nilainya, tetapi tidak menyebut sebarang jumlah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kelantan","type":"text","marks":[{"type":"bold"}]},{"text":" mempunyai bukti paling nipis antara enam ini. Carian di laman JAHEAIK tidak mengembalikan sebarang hasil untuk \"mas kahwin\" mahupun \"mahar\", dan poster fi rasmi jabatan itu juga tidak menyebutnya. Kesenyapian itu selaras dengan tiada kadar ditetapkan, tetapi kesenyapian bukan satu kenyataan rasmi.","type":"text"}]},{"type":"paragraph","content":[{"text":"Ada juga dakwaan yang beredar bahawa Kelantan mengira wang hantaran sebagai mas kahwin. Jejak dakwaan itu berakhir pada sebuah kertas akademik yang merujuk jadual JAKIM yang tidak ditemui dalam mana-mana penerbitan JAKIM. Ia tidak boleh dinyatakan sebagai fakta di sini.","type":"text"}]},{"type":"paragraph","content":[{"text":"Di enam bidang kuasa ini, jumlah mas kahwin ditentukan melalui persetujuan antara dua pihak, kemudian direkodkan oleh Pendaftar Nikah semasa pendaftaran perkahwinan. Pejabat Agama Islam Daerah (PAID) di daerah tempat akad dijalankan ialah tempat untuk mengesahkan kedudukan terkini.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Kadar minimum ialah lantai, bukan jumlah yang perlu dibayar","type":"text"}]},{"type":"paragraph","content":[{"text":"Kadar minimum ialah angka terendah yang diterima oleh negeri berkenaan, bukan jumlah yang perlu dibayar. Warta Selangor menyebutnya secara terang, iaitu RM300 \"tanpa ada had maksima\".","type":"text"}]},{"type":"paragraph","content":[{"text":"Jabatan Mufti Pulau Pinang, memetik kitab al-Fiqh al-Manhaji, menyatakan bahawa \"mas kahwin tidak mempunyai kadar minimum dan maksimumnya\". Kenyataan itu ialah kedudukan fiqh, bukan kadar pentadbiran mana-mana negeri, dan kedua-duanya perlu dibaca berasingan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dalam amalan, jumlah sebenar ditentukan oleh dua keluarga. Perbincangan itu selalunya berlaku serentak dengan perbincangan duit hantaran, dan di situlah kekeliruan paling kerap timbul. Dua angka itu perkara berbeza dan lebih mudah dirundingkan satu per satu. Perkara yang berlaku apabila jumlah melebihi kadar minimum diterangkan dalam ","type":"text"},{"text":"mas kahwin melebihi kadar minimum","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-melebihi-kadar-minimum","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Kadar yang berubah baru-baru ini","type":"text"}]},{"type":"paragraph","content":[{"text":"Dua kadar berubah dalam tempoh tiga tahun lepas.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pahang naik daripada RM22.50 kepada RM100.","type":"text","marks":[{"type":"bold"}]},{"text":" Perubahan itu diumumkan melalui titah KDYMM Sultan Pahang pada 28 Mac 2024, dilaporkan RTM pada hari yang sama dan disusuli pengumuman portal kerajaan negeri Pahang pada 29 Mac 2024. Tarikh kuat kuasa tidak dinyatakan dalam mana-mana sumber yang ditemui, dan tiada warta dikesan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Enakmen Undang-Undang Keluarga Islam Pahang sendiri tidak menetapkan sebarang jumlah mas kahwin. Seksyen 21 hanya mewajibkan Pendaftar merekodkan nilainya, jadi kadar RM100 itu datang daripada titah, bukan daripada seksyen tersebut. Butiran penuh negeri itu ada dalam ","type":"text"},{"text":"mas kahwin Pahang","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-pahang-negeri-sembilan","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Wilayah Persekutuan naik daripada RM80 kepada RM300.","type":"text","marks":[{"type":"bold"}]},{"text":" MAIWP menetapkan kadar baharu dalam sidang mesyuarat kali ke-162 pada 22 Februari 2023, dengan perkenan KDYMM Seri Paduka Baginda Yang di-Pertuan Agong pada 19 Mei 2023. Ia berkuat kuasa 1 Oktober 2023 dan dilaporkan oleh JAWI pada 14 Ogos 2023.","type":"text"}]},{"type":"paragraph","content":[{"text":"Angka RM80 masih muncul dalam modul kursus praperkahwinan bertarikh 2019/2020, dan modul yang sama masih menunjukkan Pahang pada RM22.50. Modul itu ialah satu-satunya jadual rasmi merentas negeri yang kami temui, jadi dua barisnya sudah lapuk sementara jadual lain terus merujuknya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Johor kekal pada RM22.50 dalam setiap sumber yang ditemui. Oleh sebab Johor dan Pahang dahulunya memegang angka yang sama, dan Pahang sudah berubah, angka Johor perlu disemak semula dengan jabatan agama negeri sebelum digunakan. Kedudukan penuhnya diterangkan dalam ","type":"text"},{"text":"mas kahwin Johor","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-johor","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Langkah seterusnya sebelum tarikh akad ditetapkan","type":"text"}]},{"type":"paragraph","content":[{"text":"Empat langkah, mengikut susunan.","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kenal pasti negeri tempat akad akan dijalankan dan perkahwinan didaftarkan. Setiap negeri mempunyai enakmen undang-undang keluarga Islam dan kadarnya sendiri, jadi negeri itulah yang menentukan baris mana yang anda rujuk.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Semak baris negeri itu dalam jadual di atas, berserta tarikh dan pihak berkuasanya.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Hubungi Pejabat Agama Islam Daerah (PAID) di daerah tersebut dan tanya satu soalan yang tepat: \"Berapakah kadar minimum mas kahwin yang diterima pakai di negeri ini pada hari ini, dan bilakah ia ditetapkan?\"","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bincangkan duit hantaran sebagai perbincangan berasingan. Ia bukan mas kahwin dan tidak tertakluk pada kadar minimum negeri.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Langkah ketiga paling penting bagi Johor, Sabah dan Sarawak, kerana tiga angka itu belum disahkan semula oleh mana-mana penerbitan kerajaan negeri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Panduan penuh bagi barang, dulang dan wang yang menyusul selepas mas kahwin ada dalam ","type":"text"},{"text":"hantaran dan mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Soalan lazim","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Adakah kadar mas kahwin berbeza antara anak dara dan janda?","type":"text"}]},{"type":"paragraph","content":[{"text":"Hanya di Negeri Sembilan setakat ini. Dokumen JHEAINS bertarikh 13 Mei 2026 menetapkan RM200 bagi anak dara atau bujang dan RM100 bagi janda atau ibu tunggal. Warta Selangor pula menyatakan RM300 sama rata bagi kedua-duanya. Negeri lain tidak menyebut sebarang pembezaan dalam sumber rasmi mereka.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Berapa kadar mas kahwin di Kedah dan di Melaka?","type":"text"}]},{"type":"paragraph","content":[{"text":"Kedah tidak menetapkan sebarang kadar minimum. Seksyen 21 Enakmen Undang-Undang Keluarga Islam Kedah 2008 hanya mewajibkan nilainya direkodkan. Melaka pula menetapkan RM100, dinaikkan daripada RM40 oleh Majlis Agama Islam Melaka dalam mesyuarat 28 Disember 2015 dan berkuat kuasa 1 Jun 2016.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Adakah angka RM22.50 bagi Johor masih terpakai?","type":"text"}]},{"type":"paragraph","content":[{"text":"Belum disahkan. Angka RM22.50 muncul dalam modul kursus praperkahwinan 2019/2020 dan modul kursus Johor 2022, tetapi tiada laman kerajaan negeri Johor yang menerbitkannya pada hari ini. Sahkan dengan Jabatan Agama Islam Negeri Johor atau PAID daerah sebelum menetapkan tarikh akad.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Bolehkah mas kahwin dibayar secara hutang?","type":"text"}]},{"type":"paragraph","content":[{"text":"Borang negeri mengenali kedua-dua cara, tetapi bukan pada borang nikah, dan setiap negeri mempunyai set borangnya sendiri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Perak boleh dijadikan contoh kerana borangnya diwartakan dan boleh disemak sesiapa. Dalam Warta Kerajaan Negeri Perak, Pk. P.U. 30 bertarikh 1 Jun 2013, baris \"Mas Kahwin : ………… Tunai / Hutang\" terdapat pada Borang 7, iaitu Permohonan Untuk Mendaftarkan Perkahwinan Luar Negeri dan Perkahwinan Sukarela. Pilihan yang sama muncul sebagai \"Mas kahwin (tunai / hutang)\" pada borang tuntutan perceraian, perceraian di bawah ta''liq dan fasakh.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dua borang akad nikah biasa di Perak, iaitu Borang 4 (Catatan Daftar Perkahwinan) dan Borang 5 (Perakuan Nikah), hanya membawa ruang \"Mas kahwin\" yang terbuka tanpa pilihan itu. Cara mas kahwin direkodkan dan disahkan di negeri anda ditentukan oleh Pendaftar Nikah di PAID berkenaan.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Adakah mas kahwin sama dengan duit hantaran?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tidak. Mas kahwin ialah pemberian daripada suami kepada isteri semasa akad nikah dan menjadi hak isteri sepenuhnya. Duit hantaran pula ialah wang yang diberikan pihak lelaki kepada keluarga pengantin perempuan berdasarkan persetujuan. Hanya Selangor menyatakan wang hantaran dikira sebagai mas kahwin, mengikut warta 2010.","type":"text"}]}]}'::jsonb,
  updated_at = now()
where id = 'b1484478-a5b5-44ce-85c2-10f2c2a32d0c';

-- mas-kahwin-johor  (updated_at was 2026-08-25T09:11:31.965Z)
update articles set
  cover_image_url = 'https://images.hellokahwin.com/inspire/mas-kahwin-johor/1787649085884-mas-kahwin-johor-kad-tajuk.png',
  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-johor/1787649085884-mas-kahwin-johor-kad-tajuk/low.webp","sizeBytes":10826},"high":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-johor/1787649085884-mas-kahwin-johor-kad-tajuk/high.webp","sizeBytes":35692},"original":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-johor/1787649085884-mas-kahwin-johor-kad-tajuk.png","sizeBytes":39292}}'::jsonb,
  cover_image_smart_crops = '{"crop-16x9-og":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-johor/1787649085884-mas-kahwin-johor-kad-tajuk/crop-16x9-og.webp?v=0.5625_0.4992-g48c0b959","width":1200,"height":630},"crop-4x3-article-card":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-johor/1787649085884-mas-kahwin-johor-kad-tajuk/crop-4x3-article-card.webp?v=0.5625_0.4992-g48c0b959","width":1600,"height":1200},"crop-4x5-mobile-cover":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-johor/1787649085884-mas-kahwin-johor-kad-tajuk/crop-4x5-mobile-cover.webp?v=0.5625_0.4992-g48c0b959","width":1920,"height":2400},"crop-4.3x1-desktop-hero":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-johor/1787649085884-mas-kahwin-johor-kad-tajuk/crop-4.3x1-desktop-hero.webp?v=0.5625_0.4992-g48c0b959","width":2464,"height":700}}'::jsonb,
  cover_image_focal_point = '{"x":0.5625000000000001,"y":0.4992,"method":"saliency"}'::jsonb,
  cover_image_detection_data = '{"faces":{"disabled":"rekognition"},"labels":{"disabled":"rekognition"}}'::jsonb,
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Kadar mas kahwin yang beredar bagi Johor ialah RM22.50. Angka itu belum disahkan sebagai kadar semasa. Tiada laman kerajaan negeri Johor yang menerbitkannya pada hari ini, dan sumber terbaik yang ditemui bertarikh 2019/2020 serta 2022.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kajian Universiti Teknologi MARA (UiTM) menyifatkan angka 1935 itu sebagai had maksimum, bukan kadar minimum.","type":"text"}]},{"type":"paragraph","content":[{"text":"Mas kahwin ialah bayaran yang wajib dibayar oleh suami kepada isteri, dan enakmen undang-undang keluarga Islam negeri mentakrifkannya begitu. Enakmen ialah undang-undang yang diluluskan oleh dewan undangan negeri. Beza mas kahwin dengan hantaran dan duit hantaran diterangkan berserta sumbernya dalam ","type":"text"},{"text":"apa itu mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/apa-itu-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Berapa kadar mas kahwin di Johor?","type":"text"}]},{"type":"paragraph","content":[{"text":"Satu angka sahaja muncul dalam sumber yang ditemui, iaitu RM22.50. Tiada sumber menyebut kadar berasingan bagi perempuan yang pernah berkahwin. Sumber itu senyap tentang perkara ini, dan itu bukan pengesahan bahawa kadarnya sama.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dua dokumen membawa angka itu. Yang pertama ialah modul kursus praperkahwinan MBKPI v4, halaman 18, yang menyenaraikan kadar mengikut negeri. Fail modul itu dicipta pada Januari 2019 dan dikemas kini kali terakhir pada Januari 2020.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang kedua ialah modul kursus perkahwinan Johor MBKPPI V4 tahun 2022, slaid 37 dan 38. Modul itu menyatakan \"Kadar mas kahwin Negeri Johor ialah RM 22.50\". Dokumen itu bukan penerbitan kerajaan negeri Johor dan tidak dihoskan pada pelayan ","type":"text"},{"text":".gov.my","type":"text","marks":[{"type":"code"}]},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Portal rasmi Jabatan Agama Islam Negeri Johor (JAINJ) disemak pada 23 Ogos 2026, dan tiada kadar mas kahwin ditemui di mana-mana halamannya. Empat halaman urusan perkahwinan disemak satu per satu, iaitu kursus pra perkahwinan, permohonan kebenaran berkahwin, pendaftaran nikah dan kad perakuan nikah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Carian dalaman portal itu untuk \"mahar\" dan \"kadar bayaran\" juga tidak menemui apa-apa. Mahar ialah istilah Arab bagi mas kahwin, dan kedua-duanya merujuk perkara yang sama.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Dari mana datangnya angka RM22.50?","type":"text"}]},{"type":"paragraph","content":[{"text":"Angka itu datang daripada ","type":"text"},{"text":"Ahkam Syar''iyyah Johor 1935","type":"text","marks":[{"type":"italic"}]},{"text":", perkara 309. Kajian UiTM meneliti peruntukan itu, dan menyifatkan RM22.50 sebagai had maksimum di Johor pada waktu tersebut, bukan kadar minimum.","type":"text"}]},{"type":"paragraph","content":[{"text":"Menurut kajian itu, perkara 309 menetapkan kadar nilai mahar bagi seluruh negeri dan jajahan Johor sebanyak sekati perak. Sekati perak bersamaan 600 gram, dan nilainya ketika itu RM22.50. Kajian itu turut menyatakan bahawa RM22.50 ialah jumlah yang tinggi pada waktu tersebut.","type":"text"}]},{"type":"paragraph","content":[{"text":"Di situlah sebabnya angka ini berbaki 50 sen. Ia bukan angka yang dipilih. Ia nilai logam yang ditukar kepada ringgit hampir seabad lalu.","type":"text"}]},{"type":"paragraph","content":[{"text":"Ungkapan \"tidak lebih dan boleh kurang\" ialah pembacaan pengkaji terhadap peruntukan itu, bukan petikan daripada teks 1935. Teks asal 1935 itu sendiri tidak disemak, dan kajian itu tidak menyatakan dari mana rumusannya diambil.","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Sumber: Muhammad Najib Abd Wakil, Ikmal Hafiz Jamal, Muhammad Hasif Yahaya dan Mohamad Afandi Md Ismail, \"Mas Kahwin di Pahang: Kiraan Semula Nilai Semasa\", ","type":"text"},{"text":"Journal of Contemporary Islamic Studies","type":"text","marks":[{"type":"italic"}]},{"text":", UiTM, dalam talian 10 Mac 2021.","type":"text"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tarikh","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Apa yang direkodkan","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Sumber","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"1935","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Mahar bagi seluruh negeri dan jajahan Johor ditetapkan sebanyak sekati perak, iaitu 600 gram, bersamaan RM22.50. Disifatkan oleh pengkaji sebagai had maksimum.","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Ahkam Syar''iyyah Johor","type":"text","marks":[{"type":"italic"}]},{"text":", perkara 309, menerusi kajian UiTM 2021","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"2019/2020","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Johor RM22.50. Pahang RM22.50.","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Modul MBKPI v4, halaman 18","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"2022","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM22.50. Dokumen tidak dihoskan pada pelayan kerajaan.","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Modul kursus perkahwinan Johor MBKPPI V4, slaid 37 dan 38","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Mac 2024","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pahang naik kepada RM100 menerusi titah KDYMM Sultan Pahang. Johor tidak berubah dalam mana-mana laporan yang ditemui.","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Titah KDYMM Sultan Pahang, dilaporkan RTM","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Ogos 2026","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"JAINJ tidak menerbitkan sebarang kadar mas kahwin. Status: belum disahkan.","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Portal JAINJ, disemak 23 Ogos 2026","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Disemak pada Ogos 2026.","type":"text","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Adakah RM22.50 masih terpakai hari ini?","type":"text"}]},{"type":"paragraph","content":[{"text":"Belum disahkan, dan sebab kehati-hatian itu ialah Pahang.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pahang dahulunya memegang angka yang sama, iaitu RM22.50. Kadar Pahang dinaikkan kepada RM100 menerusi titah KDYMM Sultan Pahang pada 28 Mac 2024, dilaporkan oleh RTM pada hari yang sama.","type":"text"}]},{"type":"paragraph","content":[{"text":"Carian di akhbar Malaysia dan di laman kerajaan negeri Johor tidak menemui sebarang laporan perubahan. Ketiadaan laporan bukan bukti bahawa kadar itu kekal, cuma bukti bahawa tiada laporan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kaitan antara dua negeri itu sendiri tidak muktamad. Kajian UiTM menyebut andaian bahawa pihak berkuasa Pahang mengambil kadar RM22.50 yang diamalkan di Johor. Pengkaji menulisnya sebagai andaian, bukan sebagai fakta yang disahkan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Modul MBKPI 2019/2020 ialah satu-satunya jadual rasmi merentas negeri yang ditemui. Dua barisnya kini sudah lapuk. Pahang naik kepada RM100 pada Mac 2024, dan Wilayah Persekutuan naik kepada RM300 mulai 1 Oktober 2023.","type":"text"}]},{"type":"paragraph","content":[{"text":"Modul itu sendiri tidak cukup untuk mengesahkan baris Johor.","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiada sumber rasmi yang ditemui menyatakan sama ada RM22.50 ialah kadar minimum atau kadar maksimum di Johor pada hari ini. Perkara yang berlaku apabila jumlah yang dipersetujui melebihi kadar minimum negeri diterangkan dalam ","type":"text"},{"text":"mas kahwin melebihi kadar minimum","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-melebihi-kadar-minimum","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Bayaran dan urusan nikah di Johor","type":"text"}]},{"type":"paragraph","content":[{"text":"JAINJ tidak menerbitkan jadual fi perkahwinan yang lengkap di portalnya, mengikut semakan pada 23 Ogos 2026. Senarai enakmen Majlis Agama Islam Johor (MAIJ) pula menyenaraikan 10 instrumen, tanpa satu pun kaedah Borang dan Fi. Warta Johor bagi Kaedah-Kaedah Undang-Undang Keluarga Islam juga tidak ditemui.","type":"text"}]},{"type":"paragraph","content":[{"text":"Satu bayaran dinyatakan secara khusus, iaitu Kad Perakuan Nikah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kad Perakuan Nikah, bayaran pemprosesan RM40.00.","type":"text","marks":[{"type":"bold"}]},{"text":" Permohonan dibuat di Pejabat Kadi Daerah selepas akad nikah didaftarkan. Dua keping kad dikeluarkan, satu untuk suami dan satu untuk isteri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dokumen yang perlu dikemukakan, mengikut senarai JAINJ:","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Salinan kad pengenalan suami dan isteri.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Salinan Sijil Nikah negeri Johor.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dua keping gambar suami, digalakkan bersongkok.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dua keping gambar isteri bertudung, ukuran pasport.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bayaran pemprosesan RM40.00.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"JAINJ menyatakan tempoh siap kad ialah tiga bulan dari waktu serahan dokumen. Halaman jabatan itu juga menegaskan kad tersebut dikeluarkan oleh Jabatan Agama Islam Negeri Johor sahaja.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dalam notis bertarikh 10 Jun 2026, JAINJ menyatakan ia hanya mengiktiraf Kad Perakuan Nikah yang dikeluarkan secara rasmi oleh pihak berkuasa agama negeri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Permohonan kebenaran berkahwin, pendaftaran nikah dan pendaftaran kursus praperkahwinan di Johor semuanya disalurkan melalui Sistem Pengurusan Perkahwinan Islam Malaysia (SPPIM). Kadar bayaran kursus tidak dinyatakan pada halaman JAINJ. Semak kadar itu pada slot SPPIM, atau tanya penganjur kursus yang berdaftar.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Cara mengesahkan kadar terkini","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiga langkah, mengikut susunan.","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Hubungi Pejabat Agama Islam Daerah atau Pejabat Kadi Daerah di daerah tempat akad akan dijalankan. Itulah pejabat yang merekodkan nilai mas kahwin pada borang nikah.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tanya soalan yang tepat: \"Berapakah kadar mas kahwin yang diterima pakai di Johor hari ini, dan bilakah ia ditetapkan?\" Minta tarikh, bukan hanya angka.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bincangkan duit hantaran secara berasingan. Ia bukan mas kahwin dan tidak tertakluk pada kadar mana-mana negeri.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Satu keadaan kerap timbul, dan lebih baik diselesaikan awal. Akad dijalankan di Johor, pengantin perempuan berasal dari negeri lain, dan dua keluarga membawa dua angka berbeza.","type":"text"}]},{"type":"paragraph","content":[{"text":"Setiap negeri mempunyai enakmen dan kadarnya sendiri, jadi baris yang perlu disemak ialah negeri tempat akad dijalankan dan perkahwinan didaftarkan. Kadar bagi 13 bidang kuasa yang lain ada dalam ","type":"text"},{"text":"mas kahwin ikut negeri","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-ikut-negeri","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Panduan penuh bagi barang, dulang dan wang yang menyusul selepas mas kahwin ada dalam ","type":"text"},{"text":"hantaran dan mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Soalan lazim","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Adakah Johor menetapkan kadar berbeza bagi janda?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiada sumber yang ditemui menyatakan pembezaan itu, dan tiada sumber menyatakan kadarnya sama. Modul MBKPI 2019/2020 dan modul kursus Johor 2022 kedua-duanya membawa satu angka sahaja, iaitu RM22.50, tanpa baris berasingan bagi janda. Setakat ini hanya Negeri Sembilan mempunyai pembezaan anak dara dan janda yang bersumber rasmi.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Adakah RM22.50 kadar minimum atau kadar tetap?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tidak dapat disahkan pada hari ini. Kajian UiTM membaca peruntukan 1935 sebagai had maksimum, dan ungkapan \"tidak lebih dan boleh kurang\" itu rumusan pengkaji, bukan petikan teks 1935. Modul kursus 2019/2020 dan 2022 pula menyebut RM22.50 tanpa menyatakan sama ada ia minimum atau maksimum.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Berapa bayaran Kad Perakuan Nikah di Johor?","type":"text"}]},{"type":"paragraph","content":[{"text":"Bayaran pemprosesan RM40.00, mengikut JAINJ, disemak pada Ogos 2026. Permohonan dibuat di Pejabat Kadi Daerah selepas akad nikah didaftarkan, berserta salinan kad pengenalan, salinan Sijil Nikah negeri Johor dan gambar pasangan. JAINJ menyatakan tempoh siap kad ialah tiga bulan dari waktu serahan dokumen.","type":"text"}]}]}'::jsonb,
  updated_at = now()
where id = 'd662bad6-eab7-4d77-bcdc-abcec603a3ec';

-- mas-kahwin-kelantan-terengganu  (updated_at was 2026-08-25T09:11:37.418Z)
update articles set
  cover_image_url = 'https://images.hellokahwin.com/inspire/mas-kahwin-kelantan-terengganu/1787649091345-mas-kahwin-kelantan-terengganu-kad-tajuk.png',
  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-kelantan-terengganu/1787649091345-mas-kahwin-kelantan-terengganu-kad-tajuk/low.webp","sizeBytes":11172},"high":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-kelantan-terengganu/1787649091345-mas-kahwin-kelantan-terengganu-kad-tajuk/high.webp","sizeBytes":38752},"original":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-kelantan-terengganu/1787649091345-mas-kahwin-kelantan-terengganu-kad-tajuk.png","sizeBytes":44425}}'::jsonb,
  cover_image_smart_crops = '{"crop-16x9-og":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-kelantan-terengganu/1787649091345-mas-kahwin-kelantan-terengganu-kad-tajuk/crop-16x9-og.webp?v=0.5313_0.4672-g48c0b959","width":1200,"height":630},"crop-4x3-article-card":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-kelantan-terengganu/1787649091345-mas-kahwin-kelantan-terengganu-kad-tajuk/crop-4x3-article-card.webp?v=0.5313_0.4672-g48c0b959","width":1600,"height":1200},"crop-4x5-mobile-cover":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-kelantan-terengganu/1787649091345-mas-kahwin-kelantan-terengganu-kad-tajuk/crop-4x5-mobile-cover.webp?v=0.5313_0.4672-g48c0b959","width":1920,"height":2400},"crop-4.3x1-desktop-hero":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-kelantan-terengganu/1787649091345-mas-kahwin-kelantan-terengganu-kad-tajuk/crop-4.3x1-desktop-hero.webp?v=0.5313_0.4672-g48c0b959","width":2464,"height":700}}'::jsonb,
  cover_image_focal_point = '{"x":0.5312500000000001,"y":0.4672,"method":"saliency"}'::jsonb,
  cover_image_detection_data = '{"faces":{"disabled":"rekognition"},"labels":{"disabled":"rekognition"}}'::jsonb,
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Kelantan dan Terengganu tidak menetapkan kadar minimum mas kahwin. Di Terengganu, Pesuruhjaya jabatan agama negeri sendiri menyatakannya pada Mac 2024. Di Kelantan pula, tiada kenyataan rasmi negeri ditemui, dan jumlahnya ditentukan melalui persetujuan lalu direkodkan oleh Pendaftar Nikah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Mas kahwin ialah bayaran yang wajib dibayar oleh suami kepada isteri, dan enakmen undang-undang keluarga Islam negeri mentakrifkannya begitu. Enakmen ialah undang-undang yang diluluskan oleh dewan undangan negeri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Ia berbeza daripada hantaran dan daripada duit hantaran, dan bezanya diterangkan berserta sumbernya dalam ","type":"text"},{"text":"apa itu mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/apa-itu-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Berapa kadar mas kahwin di Terengganu?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiada kadar minimum mas kahwin ditetapkan di Terengganu.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pada 29 Mac 2024, Utusan Malaysia melaporkan bahawa tiada sebarang ketetapan dibuat mengenai kadar mas kahwin di Terengganu setakat itu. Laporan itu memetik Pesuruhjaya Jabatan Hal Ehwal Agama Terengganu (JHEAT), M. Rozi Bidin, yang menyatakan kadar mas kahwin terserah kepada persetujuan wali pengantin.","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"\"Oleh itu, terpulang kepada kedua-dua keluarga untuk menetapkan kadar mas kahwin yang dipersetujui.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"M. Rozi Bidin, Pesuruhjaya Jabatan Hal Ehwal Agama Terengganu, dipetik Utusan Malaysia, 29 Mac 2024","type":"text"}]}]},{"type":"paragraph","content":[{"text":"Dua sumber rasmi menyokong kedudukan itu. Enakmen Undang-Undang Keluarga Islam (Terengganu) 2017, seksyen 20, tidak menyebut sebarang jumlah minimum. Senarai fi rasmi negeri juga tidak mengandungi satu pun baris mas kahwin.","type":"text"}]},{"type":"paragraph","content":[{"text":"Bagi Terengganu, angka RM300 anak dara dan RM100 janda memang beredar dalam jadual dalam talian. Angka itu tidak dapat dikesan kepada mana-mana sumber kerajaan negeri Terengganu, dan ia bercanggah dengan kenyataan Pesuruhjaya di atas. Kerana itu halaman ini tidak mengemukakannya sebagai kadar Terengganu.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Berapa kadar mas kahwin di Kelantan?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiada kadar minimum ditemui bagi Kelantan, dan tiada juga kenyataan rasmi negeri yang mengesahkan kedudukan itu.","type":"text"}]},{"type":"paragraph","content":[{"text":"Di situlah bezanya dengan Terengganu. Terengganu menyatakan kedudukannya melalui pegawai kanannya sendiri, manakala Kelantan senyap.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jabatan Hal Ehwal Agama Islam Kelantan (JAHEAIK) tidak menerbitkan sebarang kadar mas kahwin atau mahar. Mahar ialah istilah Arab bagi mas kahwin, dan kedua-duanya merujuk perkara yang sama.","type":"text"}]},{"type":"paragraph","content":[{"text":"Soalan lazim perkahwinan JAHEAIK, poster fi rasminya dan halaman tatacara e-Qaryah semuanya tidak menyebut mas kahwin. Begitu juga laman Mufti Kelantan dan laman Majlis Agama Islam dan Adat Istiadat Melayu Kelantan (MAIK), disemak pada Ogos 2026.","type":"text"}]},{"type":"paragraph","content":[{"text":"Modul kursus praperkahwinan bertarikh 2019/2020 menyenaraikan Kelantan di bawah \"tiada ketetapan\". Modul itu satu-satunya jadual rasmi merentas negeri yang ditemui, dan dua barisnya sudah lapuk, jadi ia dirujuk di sini sebagai sokongan sahaja.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kesenyapian itu selaras dengan tiada kadar ditetapkan, tetapi kesenyapian bukan satu kenyataan rasmi. Halaman ini tidak menyatakannya sebagai satu.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Adakah Kelantan mengira wang hantaran sebagai mas kahwin?","type":"text"}]},{"type":"paragraph","content":[{"text":"Dakwaan itu beredar luas, dan ia tidak dapat disahkan. Jejaknya berakhir pada satu kertas akademik tentang kadar mas kahwin di Pahang, diterbitkan dalam jurnal Ulum Islamiyyah, Jilid 36 Bil. 2, Ogos 2024.","type":"text"}]},{"type":"paragraph","content":[{"text":"Ayat tentang wang hantaran Kelantan itu berada dalam bahagian cadangan penulis sendiri, tanpa sebarang rujukan. Satu jadual dalam kertas yang sama, yang menyebut sumbernya sebagai Jabatan Kemajuan Islam Malaysia (JAKIM), menyenaraikan Kelantan sebagai \"tidak ditetapkan\".","type":"text"}]},{"type":"paragraph","content":[{"text":"Kertas itu juga bercanggah dengan dirinya sendiri. Satu bahagian sebelumnya meletakkan Kelantan antara negeri yang tidak menetapkan sebarang kadar.","type":"text"}]},{"type":"paragraph","content":[{"text":"Setakat semakan Ogos 2026, hanya Selangor menetapkan wang hantaran sebagai mas kahwin, melalui fatwa dalam Warta Kerajaan Negeri Selangor bertarikh 4 Februari 2010.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Apa maksudnya apabila negeri tidak menetapkan kadar?","type":"text"}]},{"type":"paragraph","content":[{"text":"Jumlah mas kahwin ditentukan melalui persetujuan, kemudian direkodkan oleh Pendaftar Nikah semasa perkahwinan didaftarkan. Tiga perkara tetap tidak berubah walaupun tiada kadar minimum.","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mas kahwin tetap wajib, mengikut takrif dalam enakmen undang-undang keluarga Islam negeri.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ia menjadi hak isteri sepenuhnya, kerana seksyen 2 enakmen Terengganu 2017 mentakrifkannya sebagai bayaran daripada suami kepada isteri.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nilainya direkodkan semasa perkahwinan didaftarkan, mengikut seksyen 20(2) enakmen yang sama.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Kalau dua keluarga meletakkan angka yang berbeza, mulakan dengan satu soalan kepada pejabat agama jajahan atau daerah. Di Kelantan, Pejabat Agama Jajahan tempat akad dijalankan ialah tempat untuk mengesahkan kedudukan semasa.","type":"text"}]},{"type":"paragraph","content":[{"text":"Perkara yang berlaku apabila jumlah yang dipersetujui jauh melebihi kadar minimum diterangkan dalam ","type":"text"},{"text":"mas kahwin melebihi kadar minimum","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-melebihi-kadar-minimum","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Fi rasmi perkahwinan di Kelantan dan Terengganu","type":"text"}]},{"type":"paragraph","content":[{"text":"Kedua-dua negeri tidak menetapkan kadar mas kahwin, tetapi kedua-duanya menetapkan fi bagi urusan nikah itu sendiri. Fi yang dibayar di kaunter dan mas kahwin yang diberi kepada isteri ialah dua perkara berasingan.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Terengganu","type":"text"}]},{"type":"paragraph","content":[{"text":"Fi urusan nikah di Terengganu ditetapkan secara rasmi pada 19 Disember 2019, dan ia berkuat kuasa pada tarikh yang sama.","type":"text"}]},{"type":"paragraph","content":[{"text":"Laman rasmi JHEAT sendiri tidak menerbitkan sebarang jadual fi pada hari ini, dan hos lama jabatan itu sudah tidak dapat dicapai. Angka di bawah datang daripada instrumen negeri, bukan daripada laman jabatan.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Urusan","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kadar fi","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kebenaran berkahwin, warganegara (dalam mukim atau luar mukim)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM10","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kebenaran berkahwin, bukan warganegara","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM50","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Upah nikah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM100","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Surat Perakuan Nikah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM30","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kad Perakuan Nikah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM40","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Sumber: Warta Kerajaan Negeri Terengganu, Jil. 72 No. 26, Tr. P.U. 11, Tambahan No. 8 Perundangan, Jadual Kedua, bertarikh 19hb Disember 2019. Satu pindaan diwartakan pada 27 Januari 2022, dan ia hanya menukar satu rujukan borang tanpa mengubah mana-mana kadar.","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Disemak pada Ogos 2026. Sahkan di kaunter pejabat agama daerah sebelum membuat bayaran.","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Jadual fi itu tidak menyenaraikan sebarang fi kursus praperkahwinan. Peraturan yang mengawal kursus itu juga tidak menetapkan sebarang jumlah.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Kelantan","type":"text"}]},{"type":"paragraph","content":[{"text":"Poster \"Kadar Bayaran Urusan Perkahwinan di Negeri Kelantan\" terbitan JAHEAIK menyenaraikan 17 butiran bayaran. Tiada tarikh dicetak pada mana-mana halamannya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Fail PDF poster itu membawa tarikh ubah suai 27 Februari 2023. Itu tarikh fail, bukan tarikh penerbitan, tetapi ia memberi gambaran usia angka di dalamnya.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Urusan","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kadar","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Nikah, kedua-dua pihak dari Kelantan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM126","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Nikah, satu pihak dari luar Kelantan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM125","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Nikah di mukim ketiga","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM138","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Nikah melibatkan warga asing","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM165","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kursus kahwin","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM70","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kad Nikah Pintar","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM25 seorang, RM50 sepasang","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Disemak pada Ogos 2026. Angka disalin seperti yang diterbitkan JAHEAIK. Kadar RM126 muncul dalam dua baris poster, iaitu nikah di mukim perempuan dan nikah di mukim lelaki, kedua-duanya RM126.","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Mukim ketiga bermaksud pasangan berkahwin di mukim yang bukan mukim lelaki dan bukan mukim perempuan, mengikut butiran poster itu sendiri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kadar bagi satu pihak dari luar negeri lebih rendah RM1 daripada kadar kedua-dua pihak dari Kelantan. Poster itu tidak menerangkan sebabnya, dan tiada sumber lain yang menjelaskannya.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph"}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kelantan","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Terengganu","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kadar minimum mas kahwin","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kadar minimum ditetapkan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kadar minimum ditetapkan","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Sumber","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kenyataan rasmi negeri ditemui","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pesuruhjaya JHEAT, dipetik Utusan Malaysia","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tarikh","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Disemak Ogos 2026","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"29 Mac 2024","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Fi nikah utama","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM126, kedua-dua pihak dari Kelantan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM100 upah nikah","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Disemak pada Ogos 2026.","type":"text","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Langkah mengesahkan kedudukan sebelum tarikh akad","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiga langkah, mengikut susunan.","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kenal pasti negeri dan jajahan atau daerah tempat akad akan dijalankan dan perkahwinan didaftarkan.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Hubungi pejabat agama di kawasan itu. Di Kelantan, JAHEAIK boleh dihubungi di 09-744 3633 atau melalui e-mel ","type":"text"},{"text":"jaheaik@kelantan.gov.my","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"mailto:jaheaik@kelantan.gov.my","class":null,"target":"_blank"}}]},{"text":". Di Terengganu, JHEAT boleh dihubungi di 09-625 2525 atau melalui e-mel ","type":"text"},{"text":"adminjheat@terengganu.gov.my","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"mailto:adminjheat@terengganu.gov.my","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tanya dua soalan yang tepat. Pertama: \"Adakah negeri ini menetapkan kadar minimum mas kahwin pada hari ini?\" Kedua: \"Berapakah jumlah fi yang perlu dibayar untuk urusan nikah ini?\"","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Bincangkan duit hantaran sebagai perbincangan yang berasingan. Ia bukan mas kahwin dan tidak tertakluk pada mana-mana kadar negeri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kedudukan kesemua 14 bidang kuasa, berserta pihak berkuasa dan tarikh setiap kadar, ada dalam ","type":"text"},{"text":"mas kahwin ikut negeri","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-ikut-negeri","class":null,"target":"_blank"}}]},{"text":". Panduan penuh bagi barang, dulang dan wang yang menyusul selepas akad ada dalam ","type":"text"},{"text":"hantaran dan mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Soalan lazim","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Adakah mas kahwin tetap wajib jika tiada kadar minimum?","type":"text"}]},{"type":"paragraph","content":[{"text":"Ya. Mas kahwin ialah bayaran yang wajib dibayar oleh suami kepada isteri, mengikut takrif dalam enakmen undang-undang keluarga Islam negeri. Yang tiada di Kelantan dan Terengganu ialah kadar minimum pentadbiran, bukan kewajipan itu sendiri. Jumlahnya ditentukan melalui persetujuan dan direkodkan oleh Pendaftar Nikah.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Betulkah angka mas kahwin Terengganu yang beredar itu?","type":"text"}]},{"type":"paragraph","content":[{"text":"Angka itu tidak dapat dikesan kepada mana-mana sumber kerajaan negeri Terengganu. Ia juga bercanggah dengan kenyataan Pesuruhjaya Jabatan Hal Ehwal Agama Terengganu, yang dipetik Utusan Malaysia pada 29 Mac 2024. Laporan itu menyebut tiada sebarang ketetapan dibuat mengenai kadar mas kahwin di negeri itu.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Berapa jumlah lazim diberi di Kelantan dan Terengganu?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiada sumber rasmi bagi jumlah lazim di kedua-dua negeri, dan angka yang tidak bersumber tidak dicetak di sini. Yang dapat disahkan ialah tiada kadar minimum ditetapkan. Jumlah sebenar ditentukan melalui persetujuan, dan pejabat agama jajahan atau daerah merekodkannya semasa pendaftaran.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Adakah kadar berbeza bagi janda di Kelantan atau Terengganu?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiada sumber rasmi bagi kedua-dua negeri ini yang membezakan anak dara dan janda, kerana kedua-duanya tidak menetapkan sebarang kadar. Setakat Ogos 2026, hanya Negeri Sembilan menerbitkan pembezaan itu, iaitu RM200 dan RM100. Angka itu datang daripada dokumen Jabatan Hal Ehwal Agama Islam Negeri Sembilan yang dikeluarkan pada Mei 2026.","type":"text"}]}]}'::jsonb,
  updated_at = now()
where id = 'b62d35d0-9d88-4174-9aae-1c05ef5fac59';

