  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-melebihi-kadar-minimum/1787649115004-mas-kahwin-melebihi-kadar-minimum-kad-tajuk/low.webp","sizeBytes":10528},"high":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-melebihi-kadar-minimum/1787649115004-mas-kahwin-melebihi-kadar-minimum-kad-tajuk/high.webp","sizeBytes":36542},"original":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-melebihi-kadar-minimum/1787649115004-mas-kahwin-melebihi-kadar-minimum-kad-tajuk.png","sizeBytes":39497}}'::jsonb,
  cover_image_smart_crops = '{"crop-16x9-og":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-melebihi-kadar-minimum/1787649115004-mas-kahwin-melebihi-kadar-minimum-kad-tajuk/crop-16x9-og.webp?v=0.5938_0.4672-g48c0b959","width":1200,"height":630},"crop-4x3-article-card":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-melebihi-kadar-minimum/1787649115004-mas-kahwin-melebihi-kadar-minimum-kad-tajuk/crop-4x3-article-card.webp?v=0.5938_0.4672-g48c0b959","width":1600,"height":1200},"crop-4x5-mobile-cover":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-melebihi-kadar-minimum/1787649115004-mas-kahwin-melebihi-kadar-minimum-kad-tajuk/crop-4x5-mobile-cover.webp?v=0.5938_0.4672-g48c0b959","width":1920,"height":2400},"crop-4.3x1-desktop-hero":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-melebihi-kadar-minimum/1787649115004-mas-kahwin-melebihi-kadar-minimum-kad-tajuk/crop-4.3x1-desktop-hero.webp?v=0.5938_0.4672-g48c0b959","width":2464,"height":700}}'::jsonb,
  cover_image_focal_point = '{"x":0.5937500000000001,"y":0.4672,"method":"saliency"}'::jsonb,
  cover_image_detection_data = '{"faces":{"disabled":"rekognition"},"labels":{"disabled":"rekognition"}}'::jsonb,
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Ya, di negeri yang menyatakannya. Fatwa Selangor yang diwartakan pada 4 Februari 2010 menetapkan kadar RM300 \"tanpa ada had maksima\". Di Pahang, titah Sultan Pahang pada 28 Mac 2024 menyerahkan penentuan kadar maksimum kepada kemampuan dan persetujuan suami isteri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jumlah sebenar ditentukan melalui persetujuan antara pengantin dan dua keluarga.","type":"text"}]},{"type":"paragraph","content":[{"text":"Mas kahwin ialah bayaran yang wajib dibayar oleh suami kepada isteri pada masa akad nikah, dan takrif itu tertulis dalam seksyen 2 enakmen undang-undang keluarga Islam negeri. Enakmen ialah undang-undang yang diluluskan dewan undangan negeri, dan takrif yang sama ada dalam enakmen Pulau Pinang 2004 dan enakmen Kedah 2008.","type":"text"}]},{"type":"paragraph","content":[{"text":"Mas kahwin juga hak isteri, dan Jabatan Mufti Negeri Pulau Pinang menyebutnya begitu: \"Mahar adalah hak isteri\". Mahar dan mas kahwin perkataan yang sama maksudnya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Hantaran pula ialah barang yang bertukar antara dua keluarga mengikut adat. Duit hantaran ialah wang yang diberikan pihak lelaki kepada keluarga pengantin perempuan berdasarkan persetujuan. Hanya mas kahwin yang wajib mengikut takrif enakmen itu, dan takrif penuh ketiga-tiga istilah ada dalam ","type":"text"},{"text":"apa itu mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/apa-itu-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"figureBlock","attrs":{"alt":"Dulang hantaran berisi buah-buahan — pisang, epal merah dan hijau, anggur ungu, oren dan buah naga — disusun dalam bakul jaring keemasan. Bunga tiruan merah dan putih serta hiasan burung kecil berwarna putih melengkapkan gubahan, di atas bingkai kayu beralas kain berbulu putih.","src":"https://images.hellokahwin.com/inspire/mas-kahwin-melebihi-kadar-minimum/1787649115004-images-s-dulang-buah-hantaran-mohd-hasan/high.webp","data-caption":"Kredit: mohd hasan / Pexels","data-caption-url":"https://www.pexels.com/photo/vibrant-fruit-basket-with-floral-accents-37097198/"}},{"type":"heading","attrs":{"level":2},"content":[{"text":"Adakah negeri menetapkan had maksimum mas kahwin?","type":"text"}]},{"type":"paragraph","content":[{"text":"Dua negeri menyebut hal ini terus. Kedua-duanya tidak mengenakan had daripada pihak negeri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Di Selangor ia tertulis dalam fatwa, iaitu keputusan agama rasmi yang disiarkan dalam warta kerajaan negeri.","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"\"Menetapkan had minima kadar nilai Maskahwin sebanyak RM 300.00 bagi anak dara atau janda tanpa ada had maksima. Sekiranya terdapat wang hantaran daripada pihak lelaki, ianya dikira sebagai Maskahwin.\"","type":"text"}]}]},{"type":"paragraph","content":[{"text":"Petikan itu daripada Warta Kerajaan Negeri Selangor, Jil. 63 No. 3, 4 Februari 2010, Tambahan No. 3 Perundangan (Sel. P.U. 3). Fatwa itu bertarikh 31 Disember 2009 dan berkuat kuasa 1 Januari 2010.","type":"text"}]},{"type":"paragraph","content":[{"text":"Di Pahang, titah Sultan Pahang pada 28 Mac 2024 menyebut \"penentuan kadar maksimum tertakluk kepada kemampuan dan persetujuan kedua-dua belah pihak suami dan isteri\". Kenyataan itu disiarkan dalam siaran rasmi kerajaan negeri Pahang bertarikh sama.","type":"text"}]},{"type":"paragraph","content":[{"text":"Ayat kedua dalam petikan Selangor itu peraturan Selangor, bukan peraturan kebangsaan. Wang hantaran daripada pihak lelaki dikira sebagai mas kahwin di Selangor mengikut fatwa yang sama, dan ketetapan itu tidak boleh diandaikan terpakai di negeri lain.","type":"text"}]},{"type":"paragraph","content":[{"text":"Wilayah Persekutuan menyatakan kadarnya sebagai \"tidak kurang daripada RM300.00\", mengikut Jabatan Agama Islam Wilayah Persekutuan (JAWI) pada 14 Ogos 2023. Ayat itu menetapkan had bawah, tanpa menyentuh had atas.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sesetengah dokumen negeri tidak menggunakan perkataan minimum langsung. Dokumen Jabatan Hal Ehwal Agama Islam Negeri Sembilan (JHEAINS), contohnya, hanya berkepala \"Kadar Mas Kahwin\", tanpa menyebut had minimum mahupun had maksimum.","type":"text"}]},{"type":"paragraph","content":[{"text":"Bagi Johor, Melaka, Sabah dan Sarawak, tiada dokumen rasmi kerajaan negeri ditemui setakat Ogos 2026 yang menyatakan sama ada kadarnya had minimum. Kedudukan setiap negeri disenaraikan dalam ","type":"text"},{"text":"mas kahwin ikut negeri","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-ikut-negeri","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Sahkan dengan Pejabat Agama Islam Daerah (PAID) di negeri pengantin perempuan sebelum menetapkan angka.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Siapa yang menentukan jumlah sebenar?","type":"text"}]},{"type":"paragraph","content":[{"text":"Dua keluarga yang menentukannya, bukan negeri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jabatan Hal Ehwal Agama Islam Perlis (JAIPS) menyatakannya dalam dokumennya sendiri. Dokumen tatacara perkahwinan bertarikh 23 April 2019 menyebut: \"Tiada penetapan jumlah tertentu untuk mahar. Bergantung kepada persetujuan bersama.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Cara sesebuah negeri menetapkan kadarnya pun berbeza, dan dua contohnya diterangkan dalam ","type":"text"},{"text":"mas kahwin Pahang dan Negeri Sembilan","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-pahang-negeri-sembilan","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Bagaimana dua keluarga menetapkan jumlah?","type":"text"}]},{"type":"paragraph","content":[{"text":"Mulakan daripada apa yang sudah tetap, kemudian bincangkan yang selebihnya secara berasingan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang sudah tetap ialah kadar di negeri pengantin perempuan, jika negeri itu menetapkan kadar. Enam daripada 14 bidang kuasa di Malaysia tidak menetapkan sebarang kadar, jadi titik rujukan itu tidak wujud di setiap negeri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Perlis sahaja yang menyatakannya dalam dokumen negerinya sendiri. Bagi lima yang lain, tiada kadar rasmi ditemui setakat semakan Ogos 2026.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang berubah pula ialah adat keluarga, dan itu tidak tertulis di mana-mana.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dua soalan membuka perbincangan. Kepada PAID: \"Berapa kadar mas kahwin yang digunakan di negeri ini sekarang?\" Kepada ibu bapa pengantin perempuan: \"Adakah keluarga mahu jumlah tertentu di atas kadar itu, dan berapa?\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Kalau dua keluarga menyebut angka yang berbeza, gunakan kadar di negeri pengantin perempuan sebagai titik rujukan. Sahkan jumlah akhir dengan PAID sebelum tarikh akad ditetapkan.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Mas kahwin tunai dan mas kahwin hutang","type":"text"}]},{"type":"paragraph","content":[{"text":"Enakmen menerima kedua-duanya. Seksyen 2 enakmen Pulau Pinang 2004 dan Kedah 2008 menakrifkan mas kahwin sebagai:","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"\"…sama ada berupa wang yang sebenarnya dibayar atau diakui sebagai hutang dengan atau tanpa cagaran, atau berupa sesuatu yang menurut Hukum Syarak, dapat dinilai dengan wang\"","type":"text"}]}]},{"type":"paragraph","content":[{"text":"Hukum Syarak di sini bermaksud hukum Islam yang menjadi rujukan undang-undang keluarga Islam. Maksudnya, mas kahwin boleh diserahkan pada hari akad, atau diakui sebagai hutang untuk diserahkan kemudian.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kalau jumlah itu belum diserahkan sepenuhnya pada hari akad, Pendaftar merekodkan bahagian yang dijanjikan. Seksyen 21 enakmen Kedah 2008 mewajibkan Pendaftar merekodkan nilai bahagian yang belum dijelaskan, tarikh yang dijanjikan untuk penjelasannya, dan butiran cagaran jika ada.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Apa yang direkodkan oleh Pendaftar Nikah?","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang direkodkan ialah nilai mas kahwin yang dipersetujui, bukan kadar yang ditetapkan negeri. Seksyen 21 Enakmen Undang-Undang Keluarga Islam (Kedah Darul Aman) 2008 mewajibkan Pendaftar \"menentu dan merekodkan— (a) nilai dan butir-butir lain mas kahwin\".","type":"text"}]},{"type":"paragraph","content":[{"text":"Nilai itu bukan sekadar masuk ke dalam daftar. Di Kedah, borang Surat Perakuan Nikah mempunyai ruangan \"Mas Kahwin\" dan \"Hutang / Tunai\" pada surat itu sendiri. Borang itu ditetapkan dalam Kaedah-Kaedah Undang-Undang Keluarga Islam (Borang dan Fi) 2019.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kad Perakuan Nikah pula tidak membawa ruangan itu. Format borang berbeza antara negeri, jadi semak dengan PAID bagaimana ia direkodkan di negeri pengantin perempuan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Untuk gambaran penuh tentang wang, barang dan kadar dalam majlis kahwin, rujuk ","type":"text"},{"text":"hantaran dan mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Disemak pada Ogos 2026.","type":"text","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Soalan lazim","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Adakah wang hantaran dikira sebagai mas kahwin?","type":"text"}]},{"type":"paragraph","content":[{"text":"Di Selangor, ya. Fatwa dalam Warta Kerajaan Negeri Selangor bertarikh 4 Februari 2010 menyatakan, \"Sekiranya terdapat wang hantaran daripada pihak lelaki, ianya dikira sebagai Maskahwin\". Ketetapan itu fatwa Selangor sahaja, jadi sahkan dengan PAID di negeri pengantin perempuan sebelum menetapkan angka.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Adakah mas kahwin yang lebih tinggi lebih baik?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiada dokumen negeri yang disemak mengaitkan jumlah yang lebih tinggi dengan apa-apa kedudukan agama atau sosial. Dari sudut fiqh, iaitu hukum amali dalam Islam, Jabatan Mufti Pulau Pinang memetik al-Fiqh al-Manhaji, jilid 4: \"Mas kahwin tidak mempunyai kadar minimum dan maksimumnya.\" Kenyataan itu kedudukan fiqh, bukan kadar pentadbiran negeri.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Bolehkah kadar mas kahwin sesebuah negeri berubah?","type":"text"}]},{"type":"paragraph","content":[{"text":"Ya. Kadar Wilayah Persekutuan naik daripada RM80 kepada RM300, berkuat kuasa 1 Oktober 2023, mengikut JAWI. Kadar itu ditetapkan dalam mesyuarat Majlis Agama Islam Wilayah Persekutuan (MAIWP) pada 22 Februari 2023, jadi semak kadar semasa sebelum berbincang.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Bolehkah mas kahwin diberi dalam bentuk emas atau barang?","type":"text"}]},{"type":"paragraph","content":[{"text":"Boleh, mengikut takrif dalam enakmen. Seksyen 2 enakmen Pulau Pinang 2004 dan Kedah 2008 menerima mas kahwin \"berupa sesuatu yang menurut Hukum Syarak, dapat dinilai dengan wang\". Dokumen JAIPS bertarikh 23 April 2019 pula meminta jumlah yang bernilai ditetapkan untuk urusan pentadbiran, dan nilainya tetap direkodkan.","type":"text"}]}]}'::jsonb,
  updated_at = now()
where id = 'b2191993-232b-4be5-b516-d20b6cc3a3ab';

-- mas-kahwin-pahang-negeri-sembilan  (updated_at was 2026-08-25T09:11:49.379Z)
update articles set
  cover_image_url = 'https://images.hellokahwin.com/inspire/mas-kahwin-pahang-negeri-sembilan/1787649103060-mas-kahwin-pahang-negeri-sembilan-kad-tajuk.png',
  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-pahang-negeri-sembilan/1787649103060-mas-kahwin-pahang-negeri-sembilan-kad-tajuk/low.webp","sizeBytes":11410},"high":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-pahang-negeri-sembilan/1787649103060-mas-kahwin-pahang-negeri-sembilan-kad-tajuk/high.webp","sizeBytes":38226},"original":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-pahang-negeri-sembilan/1787649103060-mas-kahwin-pahang-negeri-sembilan-kad-tajuk.png","sizeBytes":41948}}'::jsonb,
  cover_image_smart_crops = '{"crop-16x9-og":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-pahang-negeri-sembilan/1787649103060-mas-kahwin-pahang-negeri-sembilan-kad-tajuk/crop-16x9-og.webp?v=0.5938_0.4672-g48c0b959","width":1200,"height":630},"crop-4x3-article-card":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-pahang-negeri-sembilan/1787649103060-mas-kahwin-pahang-negeri-sembilan-kad-tajuk/crop-4x3-article-card.webp?v=0.5938_0.4672-g48c0b959","width":1600,"height":1200},"crop-4x5-mobile-cover":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-pahang-negeri-sembilan/1787649103060-mas-kahwin-pahang-negeri-sembilan-kad-tajuk/crop-4x5-mobile-cover.webp?v=0.5938_0.4672-g48c0b959","width":1920,"height":2400},"crop-4.3x1-desktop-hero":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-pahang-negeri-sembilan/1787649103060-mas-kahwin-pahang-negeri-sembilan-kad-tajuk/crop-4.3x1-desktop-hero.webp?v=0.5938_0.4672-g48c0b959","width":2464,"height":700}}'::jsonb,
  cover_image_focal_point = '{"x":0.5937500000000001,"y":0.4672,"method":"saliency"}'::jsonb,
  cover_image_detection_data = '{"faces":{"disabled":"rekognition"},"labels":{"disabled":"rekognition"}}'::jsonb,
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Kadar mas kahwin Pahang ialah RM100, selepas titah Sultan Pahang pada 28 Mac 2024. Kadar mas kahwin Negeri Sembilan pula ialah RM200 bagi anak dara atau bujang, dan RM100 bagi janda atau ibu tunggal. Kedua-dua angka itu kadar minimum, bukan jumlah akhir.","type":"text"}]},{"type":"paragraph","content":[{"text":"RTM melaporkan angka Pahang pada hari titah itu dibaca, dan portal kerajaan negeri menyiarkannya semula pada 29 Mac 2024. Angka Negeri Sembilan datang daripada dokumen Jabatan Hal Ehwal Agama Islam Negeri Sembilan (JHEAINS), muka surat 10. Disemak pada Ogos 2026.","type":"text"}]},{"type":"paragraph","content":[{"text":"Mas kahwin ialah bayaran yang wajib dibayar oleh suami kepada isteri. Enakmen undang-undang keluarga Islam negeri, iaitu undang-undang yang diluluskan oleh dewan undangan negeri, mentakrifkannya begitu.","type":"text"}]},{"type":"paragraph","content":[{"text":"Ia berbeza daripada hantaran dan daripada duit hantaran. Bezanya diterangkan berserta sumbernya dalam ","type":"text"},{"text":"apa itu mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/apa-itu-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Berapa kadar mas kahwin di Pahang?","type":"text"}]},{"type":"paragraph","content":[{"text":"RM100. Sultan Pahang, Al-Sultan Abdullah Ri''ayatuddin Al-Mustafa Billah Shah, menetapkannya melalui titah pada 28 Mac 2024. Titah ialah perintah rasmi seorang sultan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Portal kerajaan negeri Pahang menyiarkan titah baginda begini:","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"\"Maka hari ini, saya dengan ini memperkenankan pindaan kadar mas kahwin di Negeri Pahang iaitu bermula dengan kadar RM100.\"","type":"text"}]}]},{"type":"paragraph","content":[{"text":"RTM melaporkan titah yang sama pada hari ia dibaca.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sebelum itu, kadar Pahang ialah RM22.50. Menurut titah yang sama, angka lama itu sudah diamalkan sejak tahun 1900.","type":"text"}]},{"type":"paragraph","content":[{"text":"Tarikh kuat kuasa tidak dinyatakan. Tiada satu pun sumber rasmi yang disemak menyebut tarikh itu, dan tiada warta kerajaan negeri ditemui.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sumber Pahang juga tidak menyatakan sebarang perbezaan antara anak dara dan janda. Satu kadar sahaja disebut.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Kadar ini tidak datang daripada seksyen 21","type":"text"}]},{"type":"paragraph","content":[{"text":"Beberapa laporan mengaitkan RM100 dengan Seksyen 21(1) Enakmen Undang-Undang Keluarga Islam Pahang 2005.","type":"text"}]},{"type":"paragraph","content":[{"text":"Seksyen itu tidak meletakkan sebarang angka. Ia hanya menghendaki Pendaftar menentukan dan merekodkan nilai mas kahwin sesuatu perkahwinan. Kadar RM100 datang daripada titah, bukan daripada seksyen tersebut.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Berapa kadar mas kahwin di Negeri Sembilan?","type":"text"}]},{"type":"paragraph","content":[{"text":"RM200 bagi anak dara atau bujang, dan RM100 bagi janda atau ibu tunggal. Kedua-dua angka itu tersenarai di bawah tajuk \"KADAR MAS KAHWIN\" dalam dokumen JHEAINS, \"Urusan Perkahwinan, Perceraian & Rujuk\", muka surat 10.","type":"text"}]},{"type":"paragraph","content":[{"text":"Fail dokumen itu dijana pada 13 Mei 2026. Itu sumber rasmi kadar mas kahwin paling terkini yang ditemui bagi mana-mana negeri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Setakat Ogos 2026, Negeri Sembilan ialah satu-satunya negeri yang membahagikan kadar anak dara dan janda dalam sumber rasmi semasa.","type":"text"}]},{"type":"paragraph","content":[{"text":"Negeri lain tidak menyebut status pengantin perempuan. Itu bermakna sumbernya senyap, bukan bermakna kadarnya sama.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Mengapa kadar janda lebih rendah?","type":"text"}]},{"type":"paragraph","content":[{"text":"Dokumen JHEAINS menyenaraikan kedua-dua angka tanpa memberikan sebabnya. Tarikh kadar itu ditetapkan juga tidak disebut. Tiada kenyataan rasmi Negeri Sembilan ditemui yang menjelaskan asas perbezaan itu, jadi sebabnya tidak dinyatakan di sini.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Apa itu adat perpatih?","type":"text"}]},{"type":"paragraph","content":[{"text":"Adat perpatih ialah sistem adat di Negeri Sembilan yang mengira keturunan dan harta pusaka melalui sebelah ibu. Pemetaan Budaya Jabatan Kebudayaan dan Kesenian Negara (JKKN) menyebutnya sebagai \"sistem keturunan matrilineal, di mana harta pusaka dan keturunan disalurkan melalui garis ibu\".","type":"text"}]},{"type":"paragraph","content":[{"text":"Kebanyakan negeri lain mengamalkan adat temenggung, iaitu sistem yang mengira keturunan melalui sebelah bapa.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Apa yang berubah dalam perkahwinan adat perpatih?","type":"text"}]},{"type":"paragraph","content":[{"text":"Siapa yang duduk dalam rundingan berubah. Angka mas kahwin tidak.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kajian Universiti Kebangsaan Malaysia di Luak Rembau, diterbitkan dalam Jurnal Wacana Sarjana Jilid 10(1) pada April 2026, merekodkan tiga perkara.","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pihak lelaki menjemput buapak, iaitu ketua adat bagi satu kelompok keluarga, sebelum adat merisik bermula. Jemputan itu dibawa bersama tepak sirih.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Semasa merisik, tumpuan buapak ialah bertanyakan suku pihak yang dirisik. Suku ialah kelompok keturunan sebelah ibu.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Semasa menghantar cincin, buapak memilih dua atau tiga orang sebagai utusan untuk membawa cincin ke rumah pihak perempuan. Buapak sebelah perempuan yang menerima dan memeriksa cincin itu.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Kajian itu juga menyatakan pasangan daripada suku yang sama tidak boleh meneruskan perkahwinan, kerana ia dianggap melanggar aturan adat perpatih.","type":"text"}]},{"type":"paragraph","content":[{"text":"Skopnya terhad kepada Luak Rembau. Amalan boleh berbeza antara satu kawasan dengan kawasan lain, dan antara keluarga.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kadar mas kahwin pula tidak berubah kerana adat. Angka RM200 dan RM100 daripada JHEAINS terpakai di seluruh Negeri Sembilan. Tiada sumber rasmi ditemui yang memberikan pengecualian kepada keluarga yang mengamalkan adat perpatih.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Bolehkah pasangan sesuku berkahwin?","type":"text"}]},{"type":"paragraph","content":[{"text":"Menurut Jabatan Mufti Kerajaan Negeri Sembilan, boleh. Jawapan jabatan itu pada 24 Jun 2019: \"Dalam Islam, nikah sesuku dibolehkan asalkan dengan bukan mahram.\" Mahram bermaksud golongan yang haram dinikahi, seperti yang disenaraikan dalam surah al-Nisa'' ayat 23.","type":"text"}]},{"type":"paragraph","content":[{"text":"Larangan sesuku itu datang daripada adat. Jawapan jabatan mufti pula menyatakan kedudukan dari sudut hukum Islam.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kalau keluarga anda berdepan dengan soalan ini, bawa kedua-duanya sekali. Tanya buapak untuk kedudukan adat, dan pejabat agama untuk urusan pendaftaran nikah.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Kesilapan yang masih beredar tentang dua kadar ini","type":"text"}]},{"type":"paragraph","content":[{"text":"Perubahan Pahang masih baharu. Angka lama RM22.50 masih tersenarai dalam modul kursus praperkahwinan bertarikh 2019/2020, iaitu satu-satunya jadual rasmi merentas negeri yang ditemui.","type":"text"}]},{"type":"paragraph","content":[{"text":"Semakan pada 23 Ogos 2026 terhadap halaman muka pertama Google menunjukkan satu corak lain. Ada halaman yang meletakkan lajur janda RM100 untuk Pahang, di sebelah angka RM100 yang betul. Tiada sumber Pahang yang menyatakan sebarang perbezaan mengikut status pengantin perempuan, jadi lajur itu tiada asas.","type":"text"}]},{"type":"paragraph","content":[{"text":"Bagi Negeri Sembilan pula, angka RM300 hingga RM1,000 beredar dalam carian sebagai kadar minimum. Ia bukan kadar yang diterbitkan JHEAINS, iaitu RM200 dan RM100. Tiada pihak berkuasa Negeri Sembilan menerbitkan julat sedemikian.","type":"text"}]},{"type":"paragraph","content":[{"text":"Corak yang serupa berlaku di negeri yang memang tidak menetapkan sebarang kadar, seperti yang dihuraikan dalam ","type":"text"},{"text":"mas kahwin Kelantan dan Terengganu","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-kelantan-terengganu","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Bayaran rasmi di Pahang dan Negeri Sembilan","type":"text"}]},{"type":"paragraph","content":[{"text":"Kadar mas kahwin bukan satu-satunya angka yang perlu disediakan. Ini bayaran yang disenaraikan sendiri oleh kedua-dua jabatan.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Negeri","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Bayaran","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kadar","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Negeri Sembilan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Fi kebenaran berkahwin, kedua-duanya warganegara","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM10","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Negeri Sembilan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Fi kebenaran berkahwin, warganegara dengan warga asing","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM50","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Negeri Sembilan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Fi kebenaran berkahwin, bukan warganegara (MyPR atau MyKAS)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM50","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Negeri Sembilan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kebenaran tempat nikah, berlainan daerah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM10","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Negeri Sembilan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Surat Perakuan Nikah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM30","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Negeri Sembilan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kad Perakuan Nikah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM30","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Negeri Sembilan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Upah jurunikah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM120","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Negeri Sembilan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Upah saksi","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM40 seorang, bagi 2 orang","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pahang","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Bayaran permohonan kebenaran berkahwin","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM15","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Sumber: dokumen JHEAINS \"Urusan Perkahwinan, Perceraian & Rujuk\"; sistem e-Munakahat Jabatan Agama Islam Pahang (JAIP). Disemak pada 23 Ogos 2026.","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Jadual e-Munakahat JAIP menyenaraikan satu bayaran itu sahaja. Bayaran pendaftaran nikah, upah jurunikah dan upah saksi tidak tersenarai di situ, jadi tanyakan kadarnya terus di Pejabat Agama Islam Daerah (PAID).","type":"text"}]},{"type":"paragraph","content":[{"text":"Satu baris dalam dokumen JHEAINS menjawab soalan yang kerap timbul: \"Lain-lain bayaran adalah di luar ketetapan JHEAINS & MAINS.\" Maksudnya, apa-apa bayaran lain di luar senarai itu bukan kadar yang ditetapkan oleh JHEAINS atau Majlis Agama Islam Negeri Sembilan (MAINS).","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Cara mengesahkan kadar untuk kes anda","type":"text"}]},{"type":"paragraph","content":[{"text":"Kadar minimum ialah lantai, bukan jumlah yang mesti dibayar. Jumlah sebenar dipersetujui antara pengantin, dan Pendaftar merekodkannya semasa akad nikah. Penjelasan penuh ada dalam ","type":"text"},{"text":"mas kahwin melebihi kadar minimum","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-melebihi-kadar-minimum","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Di Pahang, permohonan dibuat melalui sistem e-Munakahat JAIP. Di Negeri Sembilan, permohonan dibuat dalam talian dan boleh dihantar sehingga tiga bulan sebelum tarikh yang dicadangkan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Permohonan pihak perempuan tidak boleh dipinda selepas permohonan pihak lelaki dihantar, jadi semak butiran sebelum menghantar.","type":"text"}]},{"type":"paragraph","content":[{"text":"Untuk pengesahan, hubungi PAID di daerah pengantin perempuan. Tanya dua soalan. Berapa kadar minimum mas kahwin yang direkodkan di daerah ini pada hari ini? Berapa jumlah keseluruhan bayaran bagi permohonan ini?","type":"text"}]},{"type":"paragraph","content":[{"text":"Kadar negeri lain ada dalam senarai penuh ","type":"text"},{"text":"mas kahwin ikut negeri","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-ikut-negeri","class":null,"target":"_blank"}}]},{"text":". Konteks adat yang lebih luas ada di ","type":"text"},{"text":"hantaran dan mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Soalan lazim","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Adakah kadar mas kahwin di Pahang berbeza untuk janda?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tidak. Tiada sumber rasmi Pahang yang menyatakan perbezaan itu. Titah Sultan Pahang pada 28 Mac 2024, laporan RTM dan portal kerajaan negeri semuanya menyebut satu kadar sahaja, iaitu RM100. Halaman yang menunjukkan lajur janda berasingan untuk Pahang tidak memetik sebarang sumber negeri.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Bila kadar RM100 di Pahang mula berkuat kuasa?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tarikh itu tidak dinyatakan. Titah dibaca pada 28 Mac 2024, RTM melaporkannya hari yang sama, dan portal kerajaan negeri menyiarkannya pada 29 Mac 2024. Tiada satu pun daripada sumber tersebut menyebut tarikh kuat kuasa, dan tiada warta kerajaan negeri ditemui setakat Ogos 2026.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Di mana kadar mas kahwin Negeri Sembilan diterbitkan?","type":"text"}]},{"type":"paragraph","content":[{"text":"Dalam dokumen JHEAINS bertajuk \"Urusan Perkahwinan, Perceraian & Rujuk\", di muka surat 10, di bawah tajuk \"KADAR MAS KAHWIN\". Fail itu dijana pada 13 Mei 2026 dan boleh dimuat turun dari laman JHEAINS. Dokumen yang sama turut menyenaraikan bayaran rasmi urusan nikah.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Bolehkah mas kahwin melebihi kadar minimum?","type":"text"}]},{"type":"paragraph","content":[{"text":"Boleh. Titah Sultan Pahang menyebut kadar itu \"bermula dengan kadar RM100\", iaitu titik permulaan. Dokumen JHEAINS juga menggunakan perkataan kadar, bukan jumlah tetap. Jumlah sebenar dipersetujui antara pengantin dan direkodkan oleh Pendaftar semasa akad nikah, mengikut enakmen keluarga Islam negeri masing-masing.","type":"text"}]}]}'::jsonb,
  updated_at = now()
where id = '99d59b25-a0fa-4108-94b4-7ff774bb064e';

-- mas-kahwin-perak  (updated_at was 2026-08-25T09:11:43.396Z)
update articles set
  cover_image_url = 'https://images.hellokahwin.com/inspire/mas-kahwin-perak/1787649097185-mas-kahwin-perak-kad-tajuk.png',
  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-perak/1787649097185-mas-kahwin-perak-kad-tajuk/low.webp","sizeBytes":10482},"high":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-perak/1787649097185-mas-kahwin-perak-kad-tajuk/high.webp","sizeBytes":35686},"original":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-perak/1787649097185-mas-kahwin-perak-kad-tajuk.png","sizeBytes":38178}}'::jsonb,
  cover_image_smart_crops = '{"crop-16x9-og":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-perak/1787649097185-mas-kahwin-perak-kad-tajuk/crop-16x9-og.webp?v=0.3438_0.4992-g48c0b959","width":1200,"height":630},"crop-4x3-article-card":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-perak/1787649097185-mas-kahwin-perak-kad-tajuk/crop-4x3-article-card.webp?v=0.3438_0.4992-g48c0b959","width":1600,"height":1200},"crop-4x5-mobile-cover":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-perak/1787649097185-mas-kahwin-perak-kad-tajuk/crop-4x5-mobile-cover.webp?v=0.3438_0.4992-g48c0b959","width":1920,"height":2400},"crop-4.3x1-desktop-hero":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-perak/1787649097185-mas-kahwin-perak-kad-tajuk/crop-4.3x1-desktop-hero.webp?v=0.3438_0.4992-g48c0b959","width":2464,"height":700}}'::jsonb,
  cover_image_focal_point = '{"x":0.34375000000000006,"y":0.4992,"method":"saliency"}'::jsonb,
  cover_image_detection_data = '{"faces":{"disabled":"rekognition"},"labels":{"disabled":"rekognition"}}'::jsonb,
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Perak tidak menetapkan kadar minimum mas kahwin. Setakat semakan Ogos 2026, tiada kadar mas kahwin Perak yang diterbitkan oleh mana-mana pihak berkuasa negeri. Warta kerajaan negeri yang mengandungi borang dan fi perkahwinan tidak menyebut sebarang jumlah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jumlahnya ditentukan melalui persetujuan dua pihak, kemudian direkodkan dalam borang nikah. Yang ditetapkan secara rasmi di Perak ialah fi urusan perkahwinan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Mas kahwin ialah bayaran yang wajib dibayar oleh suami kepada isteri. Takrif itu terkandung dalam seksyen 2 enakmen undang-undang keluarga Islam negeri, iaitu undang-undang yang diluluskan dewan undangan negeri. Ia disemak dalam warta Enakmen Undang-Undang Keluarga Islam (Negeri Pulau Pinang) 2004, dan teksnya sama dalam enakmen Melaka 2002 serta Kedah 2008.","type":"text"}]},{"type":"paragraph","content":[{"text":"Mas kahwin berbeza daripada hantaran dan daripada duit hantaran, dan bezanya diterangkan berserta sumbernya dalam ","type":"text"},{"text":"apa itu mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/apa-itu-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Berapa kadar mas kahwin di Perak?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiada kadar minimum ditetapkan di Perak. Jabatan Agama Islam Perak (JAIPK) tidak menerbitkan sebarang angka dalam halaman soalan lazim atau garis panduan perkahwinannya. Carian di laman Majlis Agama Islam dan Adat Melayu Perak (MAIAMP) juga tidak menemui sebarang ketetapan kadar.","type":"text"}]},{"type":"paragraph","content":[{"text":"Satu-satunya jadual rasmi merentas negeri yang ditemui ialah modul kursus praperkahwinan Islam, halaman 18. Modul itu meletakkan Perak di bawah \"Tiada ketetapan\". Failnya bertarikh 2019 dan dikemas kini 2020, dan dua barisnya sudah lapuk hari ini.","type":"text"}]},{"type":"paragraph","content":[{"text":"Perak ialah salah satu daripada enam bidang kuasa yang tidak menetapkan kadar minimum. Kedudukan setiap negeri, berserta pihak berkuasa dan tarikhnya, ada dalam ","type":"text"},{"text":"mas kahwin ikut negeri","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-ikut-negeri","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Apa yang tercatat dalam warta Perak Pk. P.U. 30?","type":"text"}]},{"type":"paragraph","content":[{"text":"Ruang kosong, bukan angka. Warta Kerajaan Negeri Perak, Jil. 66 Bil. 11, Pk. P.U. 30 bertarikh 1 Jun 2013, membawa Kaedah-Kaedah Undang-Undang Keluarga Islam (Borang dan Fi) 2013.","type":"text"}]},{"type":"paragraph","content":[{"text":"Perkataan \"mas kahwin\" muncul 20 kali merentasi 84 halaman warta itu, sepuluh kali dalam teks Melayu dan sepuluh kali lagi dalam terjemahan Inggerisnya. Setiap satu daripadanya ialah ruang kosong untuk diisi pada borang.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dua borang yang digunakan pada akad nikah di Perak ialah Borang 4, iaitu Catatan Daftar Perkahwinan di bawah seksyen 22, dan Borang 5, iaitu Perakuan Nikah di bawah seksyen 26. Kedua-duanya membawa ruang \"Mas kahwin\" diikuti ruang \"Belanja hantaran\", dan kedua-duanya dicetak kosong. Jumlahnya diisi mengikut persetujuan pasangan, bukan ditetapkan terlebih dahulu oleh negeri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Bahagian warta yang benar-benar membawa angka ialah Jadual Kedua, iaitu jadual fi. Senarai penuhnya ada di bawah.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Dari mana datangnya kadar mas kahwin Perak yang beredar?","type":"text"}]},{"type":"paragraph","content":[{"text":"Angka RM101 yang beredar luas tidak dapat dikesan kepada mana-mana sumber kerajaan negeri Perak. Ia muncul dalam jadual dalam talian dan hantaran media sosial, disalin berulang antara satu sama lain.","type":"text"}]},{"type":"paragraph","content":[{"text":"Warta 2013 tidak menyebutnya dan JAIPK tidak menerbitkannya. Modul kursus praperkahwinan pula meletakkan Perak di bawah \"Tiada ketetapan\".","type":"text"}]},{"type":"paragraph","content":[{"text":"Kalau ada ahli keluarga atau vendor menyebut satu angka sebagai kadar rasmi Perak, satu soalan sudah memadai: dokumen mana yang menyatakannya? Dokumen itu masih belum ditemui pada semakan Ogos 2026.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Siapa yang menentukan jumlah mas kahwin di Perak?","type":"text"}]},{"type":"paragraph","content":[{"text":"Jumlahnya ditentukan melalui persetujuan antara pihak lelaki dan pihak perempuan. Nilai yang dipersetujui itu diisi dalam Borang 4 dan Borang 5 dan direkodkan semasa urusan pendaftaran, seperti yang ditunjukkan oleh borang dalam warta 2013.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kerana Perak tidak menetapkan sebarang kadar minimum, tiada angka rasmi negeri untuk dijadikan titik permulaan. Tiada juga sumber rasmi yang melaporkan amalan lazim di Perak, jadi tiada julat dinyatakan di sini.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jabatan Mufti Pulau Pinang, memetik kitab al-Fiqh al-Manhaji, menyatakan bahawa \"mas kahwin tidak mempunyai kadar minimum dan maksimumnya\". Kenyataan itu ialah kedudukan fiqh, iaitu pandangan dalam ilmu hukum Islam, dan bukan kadar pentadbiran mana-mana negeri termasuk Perak.","type":"text"}]},{"type":"paragraph","content":[{"text":"Di negeri yang menetapkan kadar minimum, angka itu ialah lantai dan bukan jumlah yang perlu dibayar. Perkara yang berlaku apabila jumlah yang dipersetujui melebihi lantai itu diterangkan dalam ","type":"text"},{"text":"mas kahwin melebihi kadar minimum","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-melebihi-kadar-minimum","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Fi rasmi urusan perkahwinan di Perak","type":"text"}]},{"type":"paragraph","content":[{"text":"Enam bayaran ini disenaraikan dalam Jadual Kedua warta yang sama. Ia bahagian urusan nikah yang Perak memang tetapkan angkanya.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Urusan","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Fi","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Permohonan Kebenaran Berkahwin","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM1","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kebenaran Berkahwin","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM5","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kebenaran Berkahwin oleh Hakim Syarie","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM10","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Perakuan Nikah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM15","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kad Nikah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM20","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Salinan Perakuan Nikah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM30","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Sumber: Jadual Kedua, Kaedah-Kaedah Undang-Undang Keluarga Islam (Borang dan Fi) 2013, Warta Kerajaan Negeri Perak, Pk. P.U. 30, 1 Jun 2013. Disemak pada Ogos 2026.","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Baris ketiga ialah kebenaran daripada Hakim Syarie, iaitu hakim di mahkamah syariah, dan bukan daripada pendaftar biasa.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jadual ini bertarikh 1 Jun 2013, dan itulah instrumen fi terkini yang ditemui bagi Perak. Sahkan kadar semasa dengan pejabat agama daerah sebelum membuat sebarang bayaran.","type":"text"}]},{"type":"paragraph","content":[{"text":"Bayaran lain seperti upah jurunikah, upah saksi dan fi kursus praperkahwinan tidak termasuk dalam semakan ini, jadi ia tidak dicetak di sini.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Langkah seterusnya sebelum tarikh akad ditetapkan","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiga langkah, mengikut susunan.","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bincangkan jumlah mas kahwin antara dua keluarga secara berasingan daripada duit hantaran. Dua angka itu perkara berbeza, dan lebih mudah dirundingkan satu per satu.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Hubungi Pejabat Agama Islam Daerah (PAID) di daerah tempat akad akan dijalankan. Tanya satu soalan yang tepat: \"Adakah Perak menetapkan kadar minimum mas kahwin pada hari ini, dan berapakah fi yang terpakai bagi urusan nikah saya?\"","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sediakan jumlah yang dipersetujui untuk diisi dalam Borang 4 dan Borang 5 semasa urusan pendaftaran.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Langkah kedua paling penting di Perak, kerana tiada kadar negeri untuk disemak dan pejabat daerah itulah yang merekodkan nilainya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Panduan penuh bagi barang, dulang dan wang yang menyusul selepas mas kahwin ada dalam ","type":"text"},{"text":"hantaran dan mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Soalan lazim","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Adakah kadar mas kahwin di Perak berbeza bagi janda?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tidak. Perak tidak menetapkan sebarang kadar minimum, jadi tiada pembezaan antara anak dara dan janda untuk dinyatakan. Setakat semakan Ogos 2026, hanya Negeri Sembilan yang mempunyai pembezaan itu dalam dokumen rasmi semasa, iaitu dokumen JHEAINS bertarikh 13 Mei 2026.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Bolehkah mas kahwin di Perak dibayar secara hutang?","type":"text"}]},{"type":"paragraph","content":[{"text":"Warta negeri mengenali kedua-dua cara, tetapi bukan pada borang nikah. Dalam Warta Kerajaan Negeri Perak, Pk. P.U. 30 bertarikh 1 Jun 2013, baris \"Mas Kahwin : ………… Tunai / Hutang\" terdapat pada Borang 7, iaitu Permohonan Untuk Mendaftarkan Perkahwinan Luar Negeri dan Perkahwinan Sukarela. Pilihan yang sama muncul sebagai \"Mas kahwin (tunai / hutang)\" pada Borang 10, Borang 11 dan Borang 15, iaitu borang tuntutan bagi perceraian, perceraian di bawah ta''liq dan fasakh.","type":"text"}]},{"type":"paragraph","content":[{"text":"Borang 4 dan Borang 5, iaitu dua borang akad nikah biasa, tidak membawa pilihan itu. Ruang \"Mas kahwin\" pada kedua-duanya dibiarkan terbuka. Cara mas kahwin direkodkan dan disahkan ditentukan oleh pendaftar nikah di pejabat agama daerah berkenaan.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Siapa yang boleh mengesahkan kadar mas kahwin di Perak?","type":"text"}]},{"type":"paragraph","content":[{"text":"Mulakan dengan Pejabat Agama Islam Daerah (PAID) di daerah tempat akad akan dijalankan. Jabatan Agama Islam Perak (JAIPK) pula pihak berkuasa agama di peringkat negeri, dan halaman perkahwinannya tidak menerbitkan sebarang kadar setakat semakan Ogos 2026.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Mengapa kadar mas kahwin berbeza antara negeri?","type":"text"}]},{"type":"paragraph","content":[{"text":"Setiap negeri mempunyai enakmen undang-undang keluarga Islam dan pihak berkuasa agamanya sendiri, jadi kadar ditetapkan negeri demi negeri. Ada yang menetapkannya melalui fatwa diwartakan, ada melalui keputusan majlis agama Islam negeri. Perak tidak menggunakan mana-mana cara itu dan tidak menetapkan sebarang kadar.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Adakah mas kahwin sama dengan duit hantaran?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tidak. Mas kahwin ialah pemberian daripada suami kepada isteri semasa akad nikah, dan ia menjadi hak isteri sepenuhnya. Duit hantaran pula ialah wang yang diberikan pihak lelaki kepada keluarga pengantin perempuan berdasarkan persetujuan dua keluarga. Hanya mas kahwin yang mempunyai takrif dalam enakmen negeri.","type":"text"}]}]}'::jsonb,
  updated_at = now()
where id = 'abec9ae7-d323-4f11-9e69-17b610ae281c';

-- mas-kahwin-sabah-sarawak  (updated_at was 2026-08-25T09:11:55.452Z)
update articles set
  cover_image_url = 'https://images.hellokahwin.com/inspire/mas-kahwin-sabah-sarawak/1787649109230-mas-kahwin-sabah-sarawak-kad-tajuk.png',
  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-sabah-sarawak/1787649109230-mas-kahwin-sabah-sarawak-kad-tajuk/low.webp","sizeBytes":12312},"high":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-sabah-sarawak/1787649109230-mas-kahwin-sabah-sarawak-kad-tajuk/high.webp","sizeBytes":42270},"original":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-sabah-sarawak/1787649109230-mas-kahwin-sabah-sarawak-kad-tajuk.png","sizeBytes":48147}}'::jsonb,
  cover_image_smart_crops = '{"crop-16x9-og":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-sabah-sarawak/1787649109230-mas-kahwin-sabah-sarawak-kad-tajuk/crop-16x9-og.webp?v=0.3438_0.4992-g48c0b959","width":1200,"height":630},"crop-4x3-article-card":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-sabah-sarawak/1787649109230-mas-kahwin-sabah-sarawak-kad-tajuk/crop-4x3-article-card.webp?v=0.3438_0.4992-g48c0b959","width":1600,"height":1200},"crop-4x5-mobile-cover":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-sabah-sarawak/1787649109230-mas-kahwin-sabah-sarawak-kad-tajuk/crop-4x5-mobile-cover.webp?v=0.3438_0.4992-g48c0b959","width":1920,"height":2400},"crop-4.3x1-desktop-hero":{"url":"https://images.hellokahwin.com/inspire/mas-kahwin-sabah-sarawak/1787649109230-mas-kahwin-sabah-sarawak-kad-tajuk/crop-4.3x1-desktop-hero.webp?v=0.3438_0.4992-g48c0b959","width":2464,"height":700}}'::jsonb,
  cover_image_focal_point = '{"x":0.34375000000000006,"y":0.4992,"method":"saliency"}'::jsonb,
  cover_image_detection_data = '{"faces":{"disabled":"rekognition"},"labels":{"disabled":"rekognition"}}'::jsonb,
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Sabah dan Sarawak tidak menetapkan kadar minimum mas kahwin. Enakmen Undang-Undang Keluarga Islam 2004 di Sabah tidak menyebut sebarang jumlah, dan begitu juga Ordinan Undang-Undang Keluarga Islam 2001 di Sarawak. Kedua-duanya hanya mewajibkan Pendaftar Nikah merekodkan nilai mas kahwin yang dipersetujui.","type":"text"}]},{"type":"paragraph","content":[{"text":"Angka RM100 dan RM120 beredar luas dalam talian, tetapi tiada jabatan agama di dua negeri itu menerbitkannya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Mas kahwin ialah bayaran yang wajib dibayar oleh suami kepada isteri. Takrif itu datang daripada seksyen 2 Enakmen Undang-Undang Keluarga Islam di Pulau Pinang, Melaka dan Kedah. Enakmen Sabah 2004 dan Ordinan Sarawak 2001 tidak mengandungi takrif seumpamanya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Ia berbeza daripada hantaran dan daripada duit hantaran, dan bezanya diterangkan berserta sumbernya dalam ","type":"text"},{"text":"apa itu mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/apa-itu-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Berapa kadar mas kahwin di Sabah dan di Sarawak?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiada kadar minimum ditetapkan di kedua-dua negeri. Jumlahnya ditentukan melalui persetujuan antara dua pihak, kemudian direkodkan oleh Pendaftar Nikah semasa perkahwinan didaftarkan.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Negeri","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kadar (belum pernah berkahwin)","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kadar (janda / balu / ibu tunggal)","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pihak berkuasa","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tarikh disemak","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Sabah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kadar minimum ditetapkan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kadar minimum ditetapkan; tiada pembezaan dinyatakan dalam mana-mana sumber negeri","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Enakmen Undang-Undang Keluarga Islam 2004 (Sabah), seksyen 21","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Ogos 2026","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Sarawak","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kadar minimum ditetapkan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kadar minimum ditetapkan; tiada pembezaan dinyatakan dalam mana-mana sumber negeri","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Ordinan Undang-Undang Keluarga Islam 2001 (Sarawak), Cap. 43, seksyen 19","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Ogos 2026","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Disemak pada Ogos 2026.","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Laman Jabatan Hal Ehwal Agama Islam Negeri Sabah (JHEAINS), Majlis Ugama Islam Sabah (MUIS) dan portal ekahwin Sabah disemak pada 23 Ogos 2026. Tiada satu pun menerbitkan kadar mas kahwin.","type":"text"}]},{"type":"paragraph","content":[{"text":"Begitu juga Jabatan Agama Islam Sarawak, Majlis Islam Sarawak dan sistem urusan perkahwinan KISWA. Itulah jawapan bagi kedua-dua negeri ini, bukan maklumat yang tertinggal daripada jadual.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Undang-undang keluarga Islam di Sabah dan Sarawak","type":"text"}]},{"type":"paragraph","content":[{"text":"Setiap negeri di Malaysia mempunyai undang-undang keluarga Islamnya sendiri, dan Sabah serta Sarawak tidak terkecuali.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sabah menggunakan Enakmen Undang-Undang Keluarga Islam 2004, iaitu Enakmen No. 8 Tahun 2004. Enakmen ialah undang-undang yang diluluskan oleh dewan undangan negeri. Ia diperkenankan pada 30 Ogos 2004, dan mula berkuat kuasa pada 1 Jun 2005.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sarawak pula menggunakan Ordinan Undang-Undang Keluarga Islam 2001, Cap. 43. Ordinan ialah nama yang digunakan Sarawak bagi undang-undang negerinya, dan fungsinya sama dengan enakmen.","type":"text"}]},{"type":"paragraph","content":[{"text":"Seksyen 21 enakmen Sabah dan seksyen 19 ordinan Sarawak ialah peruntukan yang menyentuh mas kahwin. Kedua-duanya mewajibkan satu perkara sahaja, iaitu Pendaftar Nikah menentukan dan merekodkan nilai serta butiran mas kahwin yang dipersetujui.","type":"text"}]},{"type":"paragraph","content":[{"text":"Cara itu bukan khusus kepada Borneo. Kedah, Pulau Pinang dan Perak menggunakan susunan yang sama, iaitu merekod nilai tanpa menetapkan jumlah. Garis pemisah sebenar ialah antara negeri yang menetapkan kadar dan negeri yang tidak, dan kedudukan kesemua 14 bidang kuasa ada dalam ","type":"text"},{"text":"mas kahwin ikut negeri","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-ikut-negeri","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Angka RM100 dan RM120 yang beredar dalam talian","type":"text"}]},{"type":"paragraph","content":[{"text":"Angka RM100 bagi Sabah datang daripada satu sumber sahaja. Sumber itu ialah modul kursus praperkahwinan Islam terbitan Jabatan Kemajuan Islam Malaysia (JAKIM), dan fail modul itu bertarikh 2019 dan 2020.","type":"text"}]},{"type":"paragraph","content":[{"text":"Modul tersebut memang jadual rasmi merentas negeri, tetapi dua barisnya sudah lapuk. Baris Pahang dan baris Wilayah Persekutuan kedua-duanya menunjukkan angka lama. Dokumen yang salah pada dua baris tidak boleh menjadi satu-satunya sandaran bagi baris yang lain.","type":"text"}]},{"type":"paragraph","content":[{"text":"Angka RM120 bagi Sarawak muncul dalam modul yang sama. Satu-satunya jejak lain ialah laporan Utusan Online bertarikh 14 Disember 2009, iaitu 17 tahun lalu.","type":"text"}]},{"type":"paragraph","content":[{"text":"Ketika itu, Datuk Daud Abdul Rahman ialah Menteri Muda di Pejabat Ketua Menteri Sarawak (Hal Ehwal Islam). Beliau dipetik berkata: \"Buat masa ini kita masih kekal dengan kadar RM120.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Laporan asal Utusan itu sudah tiada di internet. Yang tinggal hanyalah salinannya pada sebuah blog, dan salinan blog bukan sumber rasmi. Tiada pengesahan daripada mana-mana pihak berkuasa Sarawak sejak tarikh itu.","type":"text"}]},{"type":"paragraph","content":[{"text":"Beberapa angka lain juga beredar bagi Sabah, dan tiada satu pun daripadanya membawa rujukan kepada sumber negeri. Angka berasingan bagi janda di Sarawak pula tidak mempunyai sumber langsung. Kerana itu kedua-duanya tidak dicetak di sini.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Fi rasmi urusan perkahwinan di Sabah","type":"text"}]},{"type":"paragraph","content":[{"text":"Fi perkahwinan di Sabah dibayar mengikut pakej, bukan mengikut item. Angka di bawah diambil daripada jadual fi portal ekahwin Sabah, disemak pada 23 Ogos 2026.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kategori","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pakej","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Warganegara","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Salah seorang atau pasangan bukan warganegara","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Perkahwinan sama daerah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pakej 1","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM50","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM100","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Perkahwinan sama daerah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pakej 2","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM100","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM150","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Luar daerah, salah seorang berlainan daerah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pakej 1","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM80","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM150","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Luar daerah, salah seorang berlainan daerah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pakej 2","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM130","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM200","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Luar daerah, pasangan berlainan daerah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pakej 1","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM110","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM200","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Luar daerah, pasangan berlainan daerah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pakej 2","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM160","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM250","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Disemak pada Ogos 2026.","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Pakej 1 merangkumi kebenaran berkahwin, pendaftaran perkahwinan dan surat perakuan nikah, serta sijil nikah digital. Pakej 2 ialah Pakej 1 berserta satu item lagi, iaitu Kad Perakuan Nikah (2 Unit).","type":"text"}]},{"type":"paragraph","content":[{"text":"Bayaran kepada jurunikah dan saksi tidak termasuk dalam mana-mana pakej. Jadual fi ekahwin menyatakan: \"Bayaran kepada Jurunikah dan saksi perlu dibuat pada hari pernikahan.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"JHEAINS Sabah mengenakan RM55 bagi dua keping Kad Nikah untuk satu pasangan, di kaunter kad nikah Bahagian Pentadbiran Syariah, Tingkat 10, Blok A, Wisma MUIS. Bawa dua keping gambar berukuran pasport, dan kad siap dalam lima hari bekerja.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jadual fi ekahwin pula menamakannya Kad Perakuan Nikah, jadi tanya JHEAINS sama ada Pakej 2 sudah merangkumi kad itu.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Fi rasmi urusan perkahwinan di Sarawak","type":"text"}]},{"type":"paragraph","content":[{"text":"Senarai fi di Sarawak jauh lebih pendek. Dua bayaran ini disenaraikan oleh portal perkhidmatan kerajaan Sarawak dan oleh sistem KISWA, dan kedua-dua sumber menyatakan angka yang sama.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Urusan","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Bayaran","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Permohonan kebenaran berkahwin","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM10","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Sijil Perkahwinan (KISWA) / Surat Perakuan Nikah (portal perkhidmatan Sarawak)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM15","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Disemak pada Ogos 2026.","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Bayaran lain seperti upah jurunikah, saksi dan kursus praperkahwinan tidak tersenarai dalam kedua-dua portal itu. Tanya pejabat agama daerah tempat akad akan dijalankan sebelum bajet majlis disiapkan.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Langkah mengesahkan kadar sebelum tarikh akad","type":"text"}]},{"type":"paragraph","content":[{"text":"Empat langkah, mengikut susunan.","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tentukan daerah tempat akad akan dijalankan dan perkahwinan didaftarkan. Daerah itulah yang menentukan pejabat mana yang menguruskan permohonan.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Hubungi pejabat agama Islam daerah tersebut dan tanya satu soalan yang tepat: \"Adakah negeri ini menetapkan kadar minimum mas kahwin pada hari ini, dan jika ada, bilakah ia ditetapkan?\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Di peringkat negeri, JHEAINS Sabah boleh dihubungi di +6 088 - 522 222 atau ","type":"text"},{"text":"JHEAINS@sabah.gov.my","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"mailto:JHEAINS@sabah.gov.my","class":null,"target":"_blank"}}]},{"text":". Jabatan Agama Islam Sarawak pula di +6082-507077 atau ","type":"text"},{"text":"kgjaishq@sarawak.gov.my","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"mailto:kgjaishq@sarawak.gov.my","class":null,"target":"_blank"}}]},{"text":". Kedua-dua maklumat hubungan itu disemak pada 23 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Semak jadual fi semasa di portal ekahwin Sabah atau sistem KISWA Sarawak sebelum membuat bayaran. Jadual fi berubah lebih kerap daripada kadar mas kahwin.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bincangkan duit hantaran secara berasingan daripada mas kahwin. Cara dua keluarga menetapkan angka yang dipersetujui diterangkan dalam ","type":"text"},{"text":"mas kahwin melebihi kadar minimum","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-melebihi-kadar-minimum","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Panduan penuh bagi barang, dulang dan wang yang menyusul selepas mas kahwin ada dalam ","type":"text"},{"text":"hantaran dan mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Soalan lazim","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Adakah kadar mas kahwin janda berbeza di Sabah dan Sarawak?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiada sumber negeri di kedua-dua tempat yang menyatakan sebarang pembezaan. Oleh sebab Sabah dan Sarawak tidak menetapkan kadar minimum langsung, tiada angka berasingan bagi anak dara atau janda. Angka janda yang beredar bagi Sarawak tidak mempunyai sumber, dan ia tidak dicetak di sini.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Berapa jumlah mas kahwin yang biasa di Sabah dan Sarawak?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiada sumber rasmi menerbitkan julat kebiasaan bagi kedua-dua negeri itu, dan angka tekaan tidak diberikan di sini. Yang boleh disahkan ialah kedua-dua negeri tidak menetapkan lantai. Untuk kedudukan terkini, tanya pejabat agama Islam daerah tempat akad akan didaftarkan, atau hubungi JHEAINS Sabah atau Jabatan Agama Islam Sarawak.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Kadar negeri mana yang terpakai jika pasangan lain negeri?","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiada sumber rasmi ditemui yang menyatakan kadar negeri mana yang terpakai dalam keadaan itu. Sahkan dengan pejabat agama Islam daerah tempat perkahwinan akan didaftarkan. Di situlah Pendaftar Nikah merekodkan nilai mas kahwin, mengikut seksyen 21 enakmen Sabah dan seksyen 19 ordinan Sarawak.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Adakah mas kahwin sama dengan mahar?","type":"text"}]},{"type":"paragraph","content":[{"text":"Ya. Mahar ialah istilah Arab bagi mas kahwin, dan kedua-duanya merujuk perkara yang sama. Enakmen Sabah 2004 dan Ordinan Sarawak 2001 kedua-duanya menggunakan istilah mas kahwin dalam teksnya, manakala mahar lebih kerap muncul dalam rujukan agama.","type":"text"}]},{"type":"paragraph","content":[{"text":"Takrif penuh berserta sumbernya ada dalam ","type":"text"},{"text":"apa itu mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/apa-itu-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]}]}'::jsonb,
  updated_at = now()
where id = 'd2df8447-d314-4699-88b8-685502e28389';

